INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('baalizad', 'Baalizad', 'humanoid', 'palladium-fantasy', 1, 'Any, but tend to be good or selfish', '{"IQ":"3D6","ME":"3D6","MA":"2D6","PS":"5D6","PP":"2D6","PE":"5D6","PB":"2D4","Spd":"2D4"}', 'PE+1D6', '60', NULL, '3D6', NULL, 'Hit Points are P.E. plus 1D6 per level. S.D.C. is 60 plus those from O.C.C. and physical skills. Spd 2D4 on foot, 1D6 digging.', 14, 12, '{"attacks":2,"pull":1}', '+2 to save vs magic. Attacks per melee are 2 or by O.C.C. and skills. Plasma breath is usable three times a day, once per melee, and counts as an extra attack that round. A.R. 14 is natural.', 'Underground Tunneling 40% +5% per level; Underground Architecture 30% +5% per level (detect and deactivate traps 15% +5% per level); Underground Sense of Direction 40% +5% per level, and judging surface locations 30% +5% per level (-25% in an unfamiliar area). Learns a spoken language in days: starts at the Speak Languages base and gains 5% per day to a maximum of 90%.', 'Sees in total darkness to 200 ft. A born tunneler and underground builder who can tell who dug a passage and how old it is. Eats rock, soil and gems, and needs about a gallon of water every ten days. The pincer arm cannot do fine work.', 'None.', 'Minor psychic only; roll as normal.', '7 ft', '400-500 lbs', 'About 100 years; one in 1,000 passes 800', 'Exclusive to the Baalgor Wastelands, in underground warrens', 'None, per se. Some humans, Eandroth, Gosai and Quorians have made friendly contact.', 'None, per se. Their ancestral foe is the unseen Demons of the Deep.', 'No O.C.C.s as such. With G.M. approval a player may run one as an R.C.C. equal to a Vagabond/Peasant Farmer, and it can never change class.', 'Hulking black-carapaced burrowers who surfaced in the Wastelands a few centuries ago. Most have one clawed hand and one oversized pincer; a quarter have matching arms.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.26-29'),
('cyclops-spider', 'Cyclops Spider', 'monster', 'palladium-fantasy', 0, 'Generally considered anarchist or miscreant', '{"IQ":"2D6","ME":"2D6","MA":"1D6","PS":"2D6+12","PP":"2D6+12","PE":"2D6+12","PB":"1D6","Spd":"2D6+12"}', 'PE+20', '20', NULL, '1D6', NULL, 'I.Q. is high animal intelligence.', 10, 13, '{"attacks":4,"initiative":3,"strike":3,"parry":3,"dodge":4,"damage":4}', 'The +4 to damage is in addition to any P.S. bonus. A.R. 10 is natural.', 'Prowl 75%, scale walls 88%.', 'Nightvision 60 ft, sees the invisible, leaps 10 ft high or across, walks on walls and ceilings and can hang upside down. Its shell shifts color like the first level Earth Warlock spell Chameleon.', 'None.', 'Sixth Sense, at no I.S.P. cost.', '5-6 ft long', '100-150 lbs', '10 years', 'Any rocky place; mostly the Baalgor Wastelands, the Old Kingdom Mountains and the Bruu-ga-Belimar Mountains of the Great Northern Wilderness', 'None; animal.', 'Anything that moves.', 'None; an animal.', 'A one-eyed giant spider, mutated from the Giant Cave Spider, that hunts alone by ambush at night. Giants, trolls, ogres and orcs keep them as unreliable guard beasts.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.29'),
('dragonman', 'Dragonmen', 'humanoid', 'palladium-fantasy', 1, 'Any, but tend to be selfish', '{"IQ":"2D6+2","ME":"2D6","MA":"1D6","PS":"4D6","PP":"3D6","PE":"5D6","PB":"2D4","Spd":"4D6"}', 'PE+60', '4D6', NULL, '4D6', NULL, 'Hit Points are P.E. +60, plus 1D6 per level of experience. S.D.C. is 4D6 plus any from skills.', 12, 11, '{"attacks":3,"initiative":1,"strike":1,"parry":2,"dodge":2,"damage":6}', '+2 to save vs spell magic, +3 to save vs Horror Factor. All are in addition to attribute and skill bonuses. Attacks per melee are three or by O.C.C. and combat skills. A.R. 12 is natural.', 'Most speak goblin, ogre, elf, western human and southern human at 80%. None read or write.', 'Perfect nightvision to 500 ft but poor day vision (100 ft). Sees the invisible, takes half damage from fire and heat, immune to disease, and breathes flame.', 'By O.C.C. only.', 'None.', '4 to 5.5 ft tall', '200-300 lbs', '150 years', 'Native to the Baalgor Wastelands, where few remain; most now live in the Yin-Sloth Jungles', 'None, per se. Some tribes have loose treaties with Eandroth clans.', 'None, per se. Preyed on by Gromek, giants, trolls and Western slavers.', 'Mercenary, gladiator, soldier, thief, healer and shaman, or the Nomadic Tribesman O.C.C. of the Yin-Sloth Jungles sourcebook.', 'Short, heavy, gray-scaled nomads with a ridge of horns down the spine and long talons. They look like fiends but are gentle foragers who fight savagely only when cornered.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.30-31'),
('drayback', 'Drayback', 'animal', 'palladium-fantasy', 0, 'Generally considered an anarchist animal', '{"IQ":"1D4","ME":"1D6","MA":"1D6","PS":"2D6+30","PP":"1D6+6","PE":"2D6+24","PB":"1D6+4","Spd":"1D6+6"}', 'PE+1D4x10', '1D6x10', NULL, '1D6', NULL, 'P.S. may be considered supernatural.', 13, 10, '{"attacks":2}', '+1 to save vs poison and disease, +6 to save vs Horror Factor, in addition to attribute bonuses. Lets go of a bitten victim only if it dies or goes limp, or if the Drayback loses half or more of its S.D.C. and/or Hit Points. If killed mid-bite the jaws lock: a combined strength of 32 forces them open, doing 1D6 to the victim. A.R. 13 is natural.', 'Equivalent of Land Navigation 82%.', 'Smells water up to a mile off. Carries 50 times its P.S. in pounds and pulls 200 times its P.S. Goes three days without water with ease, and up to three weeks at half speed after the first. Immune to normal fire and heat; magical fire does half damage. Rests 4-5 hours a day.', 'None.', 'None.', 'Body 10-12 ft long; the tail adds 6-12 ft', '300-500 lbs', '40 years', 'Mostly the Baalgor Wastelands; any hot or temperate region, never cold ones', 'None.', 'None.', 'Not applicable. Value: wild 250 gold, domesticated 500 to 1000 gold, eggs 50 to 100 gold.', 'A slow, purplish monitor-like lizard used across the Wastelands as a draft and riding beast, taking a driver and four passengers or a ton of cargo. Docile and tireless, but it wanders off after water when thirsty.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.31-32'),
('eandroth-pf', 'Eandroth', 'humanoid', 'palladium-fantasy', 1, 'Any, but usually anarchist or unprincipled; rogues any, but mostly good', '{"IQ":"2D6","ME":"2D6","MA":"2D6","PS":"3D6","PP":"4D6","PE":"3D6","PB":"2D6","Spd":"3D6"}', 'PE+2D4', '1D4x10', NULL, '2D6', NULL, 'Hit Points are P.E. +2D4 per level of experience. S.D.C. is 1D4x10 plus physical skills. The Psionics line gives a female before rogue stage 2D6x10 P.P.E. and 4D6 I.S.P. Male rogue: add 10 Hit Points, 2D4x10 S.D.C., 2D6 P.P.E.; attributes add I.Q. 2D6, M.E. 2D6, M.A. 1D6, P.S. 2D6, P.P. 1D6, P.E. 2D6, Spd 1D6; A.R. 12; Horror Factor 14; weight +2D4x10 lbs. Female rogue: add 10 Hit Points, 1D6x10 S.D.C., 1D6x10 P.P.E.; attributes add I.Q. 2D6, M.E. 3D6, M.A. 3D6, P.E. 1D6; A.R. 12; Horror Factor 15; weight +6D6x10 lbs; I.S.P. 2D6x10+140 plus 10 per level.', 10, 10, '{"attacks":2}', 'Bonuses: none printed. Attacks per melee are two or three as a simple hunter, or by O.C.C.; a rogue has three plus those from hand to hand skills and experience. Damage is by weapon or heat point. A.R. 10 is natural (12 for a rogue).', 'All: Horsemanship: Exotic (Silonar) +30%. Males: Wilderness Survival +20%, Land Navigation +15%, Dowsing +15%, Track and Trap Animals +15%. Females: First Aid +20%, Cook +20%, Sewing +10%, Sing +10%, Skin and Prepare Animal Hides +15%. Languages: Dragonese/Elven.', 'Lasts 1D4+2 weeks with no food or water, and works at full strength for two months on half a gallon of water a week. Shrugs off great heat and hates cold. Heat point: 1D6 minutes of motionless focus ignites one tiny spot, or knocks out a stationary foe within 90 ft for 1D4 minutes.', 'None.', 'Heat Point, common to all, at no I.S.P. cost; the target is -2 on initiative while it builds. Females before rogue stage also have Sense Evil. A female rogue is a Mind Mage with every psionic category open to her.', '4.5 to 5 ft', '75-135 lbs', '25-30 years; a male rogue about 350, a female rogue up to 500', 'Extreme desert and hot grasslands: the Baalgor Wastelands and parts of the Old Kingdom; one tribe is in the Land of the South-Winds', 'None, per se.', 'None, per se.', 'No O.C.C. before age 25, only the racial hunter skills. A male rogue then picks any O.C.C. except Psychics, starting at first level. A female rogue (about age 30) takes the Eandroth Mind Mage O.C.C. only, on the Mind Mage experience table.', 'Small reptilian nomads who cross the Wastelands in caravans on two-legged Silonar mounts. Those who outlive their violent youth turn rogue: bigger, tougher, smarter and far longer lived.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.32-35'),
('earthshaker', 'Earthshaker', 'monster', 'palladium-fantasy', 0, 'Generally considered to be anarchist', '{"IQ":"2D6+3","ME":"5D6","MA":"3D6","PS":"4D6+50","PP":"1","PE":"2D6+50","PB":"3D6","Spd":"1D6+30"}', 'PEx10', '1D4x100', NULL, '10D6+100', '10D6+100', 'P.S. and endurance are supernatural. P.P. is a flat 1. Spd is printed as 30+1D6.', 19, 17, '{"attacks":1}', '+6 to save vs spell magic, +7 to save vs psionics. Immune to Horror Factor, all poisons, disease, mind control of any kind, and spell magic of levels 1-3. Cannot dodge or parry. The one attack per melee is by magic, psionics or physical attack. Horror Factor/Awe 17: a failed save stuns for 1D4 minutes, and even a successful save stuns for one full melee round. A.R. 19 is natural.', NULL, 'Regenerates 1D4x10 per melee round and breathes underwater. Feeds on ley line nexus energy for 2-3 days, then sleeps buried for about a thousand years. Speaks by telepathy at 10th level proficiency with no I.S.P. cost.', 'At 10th level proficiency: Tongues, Ley Line Transmission, Energy Bolt, Energy Field, Energy Disruption, Extinguish Fire, Call Lightning, Memory Bank, Oracle, Second Sight, Negate Magic, Dispel Magic Barrier, Mystic Portal, Globe of Daylight, Blind, Calling, Summon Fog, Wink-Out, plus 1D6+6 spells of choice from levels 1-5.', 'At 10th level proficiency: Telepathy, Clairvoyance, Commune with Spirits, Dispel Spirits, Object Read, See the Invisible, Sense Dimensional Anomaly, Sense Evil, Sense Magic, Sixth Sense, Total Recall, Detect Psionics, Hypnotic Suggestion, Induce Nightmare, Insert Memory, Mind Bond, Mind Wipe, Invisible Haze, P.P.E. Shield, Mind Block Auto-Defense, and two Super-Psionic powers of choice.', '300 ft tall; shell nearly 1,500 ft in diameter', 'Approximately 1,000 tons', 'Effectively immortal; believed to live as long as 5,000 years', 'So far seen only in the Baalgor Wastelands; could survive any climate', 'None, per se. Quorians revere them as they sleep.', 'Other Earthshakers. Respects only adult dragons, demon/devil lords, major elementals and gods.', 'None; too lethargic to pursue an O.C.C.', 'A mountain-sized creature of magic, part snapping turtle and part horned dragon, that villages get built on while it sleeps. Awake, it flattens whatever lies between it and the next nexus without noticing.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.35-38'),
('cyclops', 'Cyclops', 'humanoid', 'palladium-fantasy', 1, 'Any, but lean toward anarchist and evil', '{"IQ":"3D6","ME":"2D6","MA":"4D6","PS":"5D6+2","PP":"4D6","PE":"4D6","PB":"2D6","Spd":"2D6"}', 'PE+1D6', '50', NULL, '1D6x10+PE', NULL, 'Hit Points are P.E. +1D6 per level of experience. S.D.C. is 50 plus O.C.C. and physical skills. P.P.E. is 1D6x10 plus the P.E. number, or by magic O.C.C.', 5, 12, '{"attacks":2,"pull":4,"roll":2}', '+3 to save vs Horror Factor, plus attribute, O.C.C. and skill bonuses. Attacks are two minimum or by O.C.C. and combat skills. Damage is typical giant damage (p.40), or by weapon or magic. The general giant note on p.40 gives most giants +1 on initiative, +2 to pull punch, +1 to roll, +3 to save vs Horror Factor and +1 to save vs poison, drugs and disease. Lightning javelins and arrows are single use and +1 to strike. A.R. 5 is natural.', 'All speak Troll and Western Human. About 40% are literate in Elven and/or Western Human or another language (+10%).', 'Nightvision 60 ft, good sight and hearing. Immune to lightning and electricity, magical included, and takes half damage from every other energy but kinetic. A third of them can forge the lightning javelins and arrows only their race may safely make.', 'By O.C.C. Lightning shafts (33% can make them): javelins light 4D6 (650-1,000 gold), medium 7D6 (1,000-1,500 gold), heavy 1D6x10 (1,600-2,400 gold), super 2D4x10 (2,000-5,000 gold); arrows light 3D6 (300-500 gold), heavy 6D6 (800-1,200 gold).', 'Standard; the same as humans.', '14 ft plus 1D4 ft', '600-1,000 lbs', '600 years; some have lived to 1,000', 'Anywhere; most common in the Wastelands, Old Kingdom, Great Northern Wilderness, and the Isle of the Cyclops', 'Kobolds, Nimro, Ogres and dragons.', 'Traditionally Changelings, Titans and Trolls. Mutual hatred with Gigantes.', 'Any, without restriction; most lean toward Men of Arms.', 'One-eyed, olive-skinned giants in silks and gold who alone hold the secret of lightning weapons. In the Wastelands they advise and arm the Nimro, or lead raiding bands of their own.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.40-41'),
('jotan', 'Jotan', 'humanoid', 'palladium-fantasy', 1, 'Any, but lean toward anarchist and evil', '{"IQ":"2D6","ME":"3D6","MA":"2D6","PS":"5D6+10","PP":"4D6+6","PE":"4D6+6","PB":"2D6","Spd":"3D6"}', 'PE+1D6', '1D4x10+40', NULL, '1D4x10', NULL, 'Hit Points are P.E. +1D6 per level of experience. P.S. is supernatural.', 5, 12, '{"attacks":3,"initiative":1,"pull":2,"roll":2}', '+1 to disarm, +3 to save vs Horror Factor, plus attribute, O.C.C. and skill bonuses. Attacks are three, or by O.C.C. and combat training +1. Damage is typical giant damage (p.40), or by weapon or magic. A.R. 5 is natural.', 'Speaks Troll/Giantese and Gobblely. Recognize Weapon Quality and Field Armorer, both at +15%, whatever the O.C.C.', 'Supernatural strength and endurance. The block prints a bare 40 ft where the other giants have nightvision. Good sight and hearing, half damage from heat and fire, and a knack for mechanics and metalwork.', 'By Witch, Warlock or Clergy O.C.C. only.', 'Standard, the same as humans.', '18 to 20 ft tall', NULL, '300 years; some live to 500', 'Anywhere; most common in the Baalgor Wastelands, the Old Kingdom and the Land of the South Winds', 'Nimro, Cyclops and Gigantes, as well as trolls, ogres, orcs and goblins.', 'Traditionally Rahu-Men, Titans, Elves, Dwarves and humans.', 'Men of arms (any), clergy, witch, warlock.', 'Bronze-skinned Earth Giants, the strongest of giantkind and its smiths and enforcers in the Wastelands. Few in number, warlike, and often found leading goblins, orcs, ogres and trolls.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.41'),
('gigantes', 'Gigantes', 'humanoid', 'palladium-fantasy', 1, 'Any, but lean toward anarchist, miscreant and diabolic', '{"IQ":"2D6","ME":"1D6","MA":"2D6","PS":"4D6+8","PP":"3D6+6","PE":"4D6+6","PB":"2D6","Spd":"4D6"}', 'PE+1D6', '1D6x10', NULL, '2D4x10', NULL, 'Hit Points are P.E. +1D6 per level of experience. S.D.C. is 1D6x10 plus mutation bonuses and physical skills. P.S. is supernatural. Horror Factor is 13 and higher depending on appearance. No Natural A.R. is printed.', NULL, 13, '{"attacks":2}', '+4 to save vs Horror Factor, plus attribute, O.C.C., skill and mutation bonuses. Attacks are 2 or by O.C.C. and combat skills. Damage is by punch, kick or weapon (giant damage, p.40) and by mutation. MUTATIONS, roll four times: 01-05 nightvision 3D6x30 ft; 06-10 see the invisible; 11-15 turn invisible at will; 16-20 impervious to fire, +20 S.D.C.; 21-22 poisonous bite 3D6; 23-24 second mouth, bite 1D6 and +1 attack in range; 25-26 single large horn, +1D6 to ram and head butt; 27-32 extra pair of arms, +1 attack; 33-40 scaly skin, +1D6x10 S.D.C.; 41-45 thick lumpy skin, +6D6 S.D.C.; 46-50 leather wings, 50% can fly at 2D6x10; 51-54 extra eye, +2 initiative, 30 ft nightvision; 55-59 heavy tail, slap 2D6; 60-64 large fangs, bite 3D6; 65-69 ape-like furred body, +15 S.D.C.; 70-75 feather wings, 50% can fly at 3D6x10; 76-80 claws, +1D6 punch damage; 81-84 large flat teeth, bite 2D4; 85-90 breathe fire, 20 ft, 3D6; 91-95 spits acid, 20 ft, 4D6; 96-00 extra leg, +20% balance, +1D4x10 speed. INSANITY, roll once, again after trauma and per 50 years alive (NPCs generally have two): 01-10 psychosis; 11-34 none; 35-44 obsession; 45-77 phobia; 78-91 neurosis; 92-00 affective disorder.', 'Instinctive swimmers (60%). All speak Giantese; some also speak Troll and/or Gobblely.', 'Strength and endurance count as supernatural. The block prints a bare 40 ft where the other giants have nightvision. Good sight and hearing. Each one carries four random mutations and at least one roll for insanity.', 'Generally unavailable.', 'Standard, about the same as humans.', '15 to 20 ft tall (14 ft +1D6 ft)', '1,000-2,000 lbs', '150 years; few live beyond 200', 'Anywhere; most common in the Yin-Sloth Jungles, the Wastelands, the Old Kingdom Mountains and the Great Northern Wilderness', 'Nimro, trolls, ogres, orcs and goblins.', 'Traditionally Titans, Rahu-Men, Elves, Dwarves, humans, Wolfen/canines and most non-giants; on bad terms with Gromek.', 'Any men of arms, clergy or witch. The book suits them best to villain NPCs.', 'Mutant giants, each one differently deformed and usually mad, who live for slaughter and eat their foes. Even other giants tend to drive them out.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.42-43'),
('nimro', 'Nimro', 'humanoid', 'palladium-fantasy', 1, 'Any, but lean towards anarchist and evil, particularly miscreant and aberrant', '{"IQ":"3D6","ME":"4D6","MA":"3D6","PS":"3D6+6","PP":"3D6+6","PE":"4D6+6","PB":"3D6","Spd":"2D6"}', 'PE+1D6', '50', NULL, '1D4x10', NULL, 'Hit Points are P.E. +1D6 per level of experience. S.D.C. is 50 plus O.C.C.s and physical skills. P.P.E. is 1D4x10 or by magic O.C.C. Strength and endurance are considered supernatural. No Natural A.R. is printed.', NULL, 11, '{"attacks":2}', '+2 to save vs Horror Factor, +1 to save vs illusions, +3 to save vs possession, all in addition to attribute, O.C.C. and skill bonuses. Attacks are 2 plus the breath attack, or by O.C.C. and combat skills. The block has no Damage line; the punches are the general giant damage of p.40.', 'Giantese, Troll and Gobblely; many also speak Elven and other languages. About 50% are literate in Elven or Western Human.', 'Nightvision 40 ft, good sight and hearing. Immune to fire, and every other energy does half damage. Breathes fire once per melee as an extra attack.', 'By O.C.C. only.', 'Standard, about the same as humans.', '15 to 18 ft tall (14 ft +1D4 ft)', '800-1,400 lbs', '300 years; some as long as 500', 'Anywhere; most common in the Wastelands, Old Kingdom and the Yin-Sloth Jungles', 'Jotan, Gigantes, ogres, trolls, orcs, goblins and fire dragons; occasionally Cyclops and Algor.', 'Traditionally Titans, elves, dwarves, humans and non-giants.', 'Any, except knight, palladin and long bowman.', 'Copper- or red-skinned fire giants with yellow eyes: schemers and organizers who are colonizing the Wastelands for the Nimro Kingdom while warring with the Gromek. Renegades among them set up as warlords.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.43'),
('gosai', 'Gosai', 'humanoid', 'palladium-fantasy', 1, 'Any, but usually selfish or aberrant evil', '{"IQ":"3D6","ME":"3D6","MA":"2D6","PS":"3D6","PP":"3D6+6","PE":"3D6","PB":"3D6","Spd":"3D6+6"}', 'PE+1D6', '3D6', NULL, '4D6', NULL, 'Hit Points are P.E. +1D6 per level. S.D.C. is 3D6 plus O.C.C./R.C.C. and physical skills.', 10, 10, '{"attacks":2,"strike":1,"parry":1,"dodge":1}', '+1 melee attack (agility and prehensile feet) on top of the 2 or by O.C.C./R.C.C. and combat skills. +2 to save vs Horror Factor, -2 to save vs poison. Touching any metal does 1D4 damage each time. A.R. 10 is natural.', '+10% to Scale Walls if the skill is taken. Speaks its own tongue and fluent Elven. HAND TO HAND: SKUDASA (Gosai Assassin R.C.C. only), by level: 1 two attacks per melee, +2 to strike; 2 +3 to parry and dodge, +2 to pull punch, +2 to roll with punch/fall; 3 all kick attacks; 4 +1 attack and +1 on initiative; 5 claws 3D6, pop kick 5D6; 6 critical strike on an unmodified 17-20; 7 hand and foot claws as paired weapons, and may parry hand held weapons; 8 leap attack, +1 on initiative, +2 to pull punch; 9 +1 attack; 10 +2 to parry and dodge; 11 body throw/flip, +1 to initiative; 12 death blow on an unmodified 20; 13 +2 to damage; 14 +1 attack; 15 +2 to strike and disarm.', 'Feet as nimble as hands, good even for picking locks. Retractable claws on hands and feet. Spring-loaded knees give a 30 ft leap in any direction and power the pop kick.', 'By O.C.C. only.', 'Standard.', '5-6 ft tall', '150-175 lbs', '60 years', 'The Baalgor Wastelands; cannot stand cold or wet climates', 'Humans, Elves and Eandroth.', 'Giants, trolls, ogres and orcs; Quorians above all.', 'Any except knight, palladin and long bowman; thief, assassin and gladiator are favored. The race also has its own Gosai Assassin R.C.C.: the Assassin O.C.C. with Hand to Hand: Skudasa and four extra skills in place of its weapon proficiencies, and no W.P., Horsemanship or Disguise.', 'Slim, hairless, red-scaled nomads brought from another world as the Elves'' assassins. Calm and methodical, allergic to metal, and they refuse to ride or own more than they can carry.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.44-46'),
('gromek-pf', 'Gromek', 'humanoid', 'palladium-fantasy', 1, 'Any, but predominantly selfish or evil', '{"IQ":"2D6+1","ME":"3D6","MA":"2D6","PS":"4D6+2","PP":"3D6","PE":"4D6","PB":"2D6","Spd":"2D6"}', 'PE+1D6', '4D6', NULL, '2D6', NULL, 'Hit Points are P.E. +1D6 per level of experience. S.D.C. is 4D6 plus physical skills. Spd is 2D6 running and 6D6+6 in flight.', 12, 14, '{"attacks":2,"initiative":2,"strike":1,"parry":2,"dodge":2,"pull":2,"roll":2}', '+4 to dodge while in flight. All are in addition to attribute and skill bonuses. Attacks are two plus those from combat skills. A.R. 12 is the tough, fine-scaled skin.', 'Own language, spoken and written. Most also speak Giantese.', 'Flies on bat-like wings, has keen hawk-like sight, and takes half damage from fire.', 'By O.C.C. only, and rare.', 'None.', '8 to 10 ft tall; females rarely over 8 ft', '600-800 lbs', '180 years', 'Mountains and tall hills in moderate to hot climates; chiefly the Baalgor Mountains, also the Yin-Sloth Jungles and the Land of the South Winds', 'Occasionally ogres, trolls or giants, though less and less.', 'Humans and most indigenous intelligent life forms; at war with giantkind.', 'All optional and Men of Arms O.C.C.s, above all mercenary, soldier, ranger, knight and palladin. Clergy and Men of Magic are open but seldom taken.', 'Winged, horned warrior aliens with a Spartan society, driven out of Mount Nimro by the giants and now holding the Baalgor Mountains against them. Fine weaponsmiths who distrust magic.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.46-47'),
('lazretheg', 'Lazretheg', 'monster', 'palladium-fantasy', 0, 'Anarchist or Miscreant', '{"IQ":"1D6+1","ME":"2D6","MA":"1D6","PS":"2D6+8","PP":"2D6+6","PE":"2D6+6","PB":"1D6","Spd":"2D6+6"}', 'PE+20', '20', NULL, '1D6', NULL, NULL, 6, 10, '{"attacks":3,"initiative":3,"strike":1}', 'Three attacks per melee, by whip or bite. I.Q. is high animal intelligence. A.R. 6 is natural.', 'Languages: none.', 'None listed. Hunts by hooking its legs to a rock, snaring prey with its tentacles, reeling it in and then draining blood through its proboscis.', 'None', 'None', '3-4 feet long (0.9-1.2 m)', '50-75 pounds (23-34 kg)', '3 years', 'Exclusive to the Baalgor Wastelands', 'None', 'None', 'None; treated as an animal.', 'Chigger-shaped blood drinker with whip tentacles, thought to come from another world. After gorging it sleeps a few days, and it favours huge hosts such as Sandwyrms and Earthshakers.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.48'),
('minotaur', 'Minotaur', 'humanoid', 'palladium-fantasy', 1, 'Any, but most are evil or selfish', '{"IQ":"2D6+1","ME":"3D6","MA":"3D6","PS":"5D6","PP":"4D6","PE":"5D6","PB":"3D6","Spd":"3D6"}', 'PE+1D6', '2D4x10', NULL, '2D6', NULL, 'Hit Points are P.E. plus 1D6 per level of experience. S.D.C. is 2D4x10 plus those gained from physical skills.', 12, 14, '{"attacks":2,"strike":1,"parry":1,"dodge":1}', 'Attacks per melee: 2 or by O.C.C. +3 to save vs Horror Factor. All bonuses are in addition to attribute and skill bonuses. Natural A.R. 12 is a tough, leathery hide. Horn charge has a 60% chance of knocking the victim down (loses one melee attack and initiative).', 'Recognize scent 22%, track by blood scent 54%. Languages: Troll/Giantese, Gobblely and Elven; 94% are illiterate.', 'Great strength and stamina, nightvision to 60 ft (18.3 m) that works in total darkness, sharp sight and hearing and a superior nose. Fire and cold do half damage.', 'Only by O.C.C., very limited; 94% of all Minotaurs are fighters.', 'Standard, same as humans.', '8 to 11 feet tall (2.4 to 3.3 m); 7 feet +1D4 additional feet', '500 to 800 pounds (225 to 360 kg)', '400 years; few live past 500', 'Southern half of the known world: in and around the Old Kingdom Mountains, the Baalgor Wastelands and parts of the Yin-Sloth jungles; by legend the Land of the Damned', 'None', 'Wary of all humanoids; lasting friendships with other races are uncommon', '94% take a man at arms O.C.C.: 40% of those mercenary, 20% assassin, the rest any other, with knights and palladins extremely rare and cast out as traitors. The other 6% are clergy or men of magic: Chaos Priest 2%, Disciple of the Old Ones 1.5%, Necromancer 1.5%, Wizard 0.3%, Earth Warlock 0.4%, other casters 0.3%. The Chaos Priest and Disciple R.C.C.s are in Old Ones, 2nd Edition.', 'Bull-headed subterranean giants with bluish-gray to black skin, few in number and hostile to anyone entering their tunnels. Mostly nomadic, fond of heavy arms taken from the slain, and half of them eat no meat. A horn sells to Alchemists for up to 1,500 gold.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.48-50'),
('mologoth', 'Mologoth', 'monster', 'palladium-fantasy', 0, 'Generally considered Miscreant or Diabolic', '{"IQ":"1D6","ME":"2D6","MA":"1D6","PS":"3D6+30","PP":"1D6+12","PE":"2D4+20","PB":"1D6+5","Spd":"2D6+20"}', 'PE+55', '1D4x10+40', NULL, '4D6', NULL, 'Average P.P.E. is printed as 15 (4D6). P.S. is considered supernatural. I.Q. is that of an instinctive predator.', 13, 14, '{"attacks":4,"initiative":1,"strike":3,"parry":3,"dodge":3}', 'Four attacks per melee by bite, stomp or claw. After a claw strike with upper claws or feet it tries to bite the same victim on its next attack at an additional +3 to strike. +8 to save vs Horror Factor; +4 to save vs magic, poison, disease and psionic attacks affecting the mind. A natural 20 on a bite swallows a troll-sized or smaller victim whole: 4D6 per melee round inside, suffocation in 1D4+2 minutes, the victim fights blind and must inflict 50 points to cut free (at least one melee round), which halves the Mologoth''s attacks, speed and bonuses. A Mologoth cut open this way with at least 20% of its Hit Points left survives on 01-50%. The tail swipe is usually accidental; the tail cannot be aimed.', 'Languages: none; animal grunts, groans and roars.', 'Enormous strength, stamina and destructive power with good speed. Fire, cold and electricity do half damage, and it heals 1D6+3 every 24 hours.', 'None', 'None', 'Roughly 50 feet (21 m) tall', NULL, '30 years, but often less', 'Exclusive to the Baalgor Wastelands so far; Gromek and giants of the Baalgor Mountains keep their numbers low', 'None, an aggressive animal', 'None, except for Sandwyrms', 'None; treated as an animal.', 'Dim-witted tyrannosaur-like predator, beige and striped, with oversized forearms and three rows of teeth. Natives trap, trick and hunt it, and arenas in the Western Empire, Lopan and the Old Kingdom buy captured ones. Its meat is edible and its teeth, claws and hide are worked into goods.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.50-52'),
('quillback', 'Quillback', 'humanoid', 'palladium-fantasy', 1, 'Mostly unprincipled or anarchist; a few scrupulous, miscreant or aberrant, but these are quite rare', '{"IQ":"2D6+8","ME":"3D6","MA":"3D6","PS":"2D6","PP":"4D6","PE":"2D6","PB":"2D6","Spd":"5D6"}', 'PE+1D6', '15', NULL, '3D6', NULL, 'Hit Points are P.E. plus 1D6 per level of experience. S.D.C. is 15 plus whatever is gained from O.C.C. and physical skills.', 10, NULL, '{"attacks":3,"strike":2,"parry":2,"dodge":3,"pull":1,"initiative":1}', 'Attacks per melee: three, or one plus O.C.C./R.C.C. and combat skills. The +1 initiative comes from Advanced Hearing, which also detects a surprise attack 96% of the time. A.R. 10 is the Quill Defense (no Natural A.R. line is printed): a physical attack with a body part must roll over 10 to strike or the attacker takes 3D6. Quills cannot be shot; lost quills regrow in 1D4+2 months. Wearing armor or clothing is virtually impossible. Horror Factor: none.', 'Track Humanoids by smell 30% +5% per level; detect extreme emotions 64%. Languages: a chittering dialect of Gobblely; many also learn Elven, Giantese and Western Human.', 'Advanced Smell: follows faint scent trails, senses strong emotion in others and knows individuals by scent. Advanced Hearing: picks up very faint sounds and is almost never surprised. Quill Defense: a coat of quills that works as body armor and as a weapon, and that can also pick locks.', 'Only Quillback shamans ever learn magic.', 'Standard', 'Four to five feet tall (1.7-2.1 m)', '75 to 100 pounds (35-45 kg)', '15 to 20 years in the wild; as long as 50 or 60 years in civilized places', 'Rocks and crevices of the Rocky Desert and forests of the Baalgor Mountains; lately exported to the Western Empire, the Land of the South Winds and the Yin-Sloth Jungles', 'Anyone proven trustworthy: Eandroth, Dragonmen, Vrill, and certain Quorians, Gosai, humans, Elves and Dwarves. Gnomes and faeries are trusted on sight.', 'Anything larger is feared, especially Baalizad, Gromeks, giants, orcs, ogres, trolls, and certain humans, elves and dwarves', 'Any man at arms except long-bowman, knight or palladin; clergy (usually shaman); psychics (mostly Psi-Mystic or Psi-Healer); vagabond; entertainers such as bard or minstrel. No men of magic. The book also gives a Quillback Scavenger R.C.C., a Vagabond variant on the Thief/Merchant experience table.', 'Small, quick, clever rodent-faced people coated in porcupine quills, gray to drab brown. They wander in short-lived groups called hutches, hoard anything shiny and tend to borrow without returning; about one in ten is a habitual thief.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.52-54'),
('quorian', 'Quorian', 'humanoid', 'palladium-fantasy', 1, 'Any, but leaning very heavily to principled, scrupulous and aberrant', '{"IQ":"3D6","ME":"2D6+2","MA":"3D6","PS":"3D6+6","PP":"3D6","PE":"3D6+6","PB":"2D6+2","Spd":"2D6"}', 'PE+1D6', '25', NULL, '3D6', NULL, 'Hit Points are P.E. plus 1D6 per level of experience. S.D.C. is 25 plus those from O.C.C./R.C.C. and physical skills.', NULL, NULL, '{"attacks":2,"initiative":1,"pull":3,"roll":1}', 'Attacks per melee: 2 or by O.C.C./R.C.C. +3 to save vs poison and disease, +20% to save vs coma/death, +2 to save vs Horror Factor. All are in addition to attribute bonuses. Damage is by punch, kick, weapon or magic/psychic attack; no figures are printed. Horror Factor: none. Quorians refuse to wear armor (shields, gauntlets and armlets are acceptable).', 'Languages: their own language and Dwarven, fluently; many are literate and study Elven, Gobblely and dialects of Human.', 'Hearing and sight equal to a human with perfect senses, plus high strength and stamina. Healing Factor: regains 3 S.D.C. every 10 minutes and 1 H.P. every 15 minutes; fire and cold do half damage; drugs, toxins, disease and poison do one third; wounds close without scars and broken bones knit ten times faster. It does not regrow limbs or raise the dead.', 'By O.C.C.', 'Standard', '6-7 feet tall (2 to 2.3 m); not considered giant-sized', '200-300 lbs (91 to 136 kg)', '50-60 years', 'Largely the Baalgor Wastelands; also seen in the Yin-Sloth Jungles, near Mount Nimro and in the Old Kingdom', 'Generally Eandroth, Dragonmen and humans; stand-offish to Dwarves and Elves; indifferent to most others', 'Gosai, giants, trolls, ogres, orcs, and anybody interfering with their quest to go home or their devotion to the Earthshakers', 'Any. Most are men at arms; wizardry and Warlock magic are growing; Diabolism and Summoning are distrusted; clergy and psychic classes are uncommon. The book also gives a Quorian Oneiromancer R.C.C., a Psi-Mystic variant.', 'Proud blue-purple warriors with red pupil-less eyes and ropy hair, brought from the world of Quoria during the Elf-Dwarf War and stranded. They feud with the Gosai, take offence easily, set great store by dream-visions, and many now settle above sleeping Earthshakers hoping to learn a way home.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.54-57'),
('rock-buzzer', 'Rock Buzzer', 'animal', 'palladium-fantasy', 0, 'Animal/insect, considered selfish', '{"IQ":"1D4","ME":"1D4+2","MA":"1D4+1","PS":"2D6+12","PP":"1D6+12","PE":"2D6+12","PB":"1D4+1","Spd":"2D6"}', 'PE+20', '2D6+50', NULL, '1D4', NULL, 'Spd 2D6 is running; flying speed is 72 (approx. 50 mph/80 km). P.S. is considered supernatural for lifting and carrying. I.Q. is low animal intelligence.', 8, 8, '{"attacks":1,"strike":-1,"dodge":2}', '+4 to dodge while in flight, +2 to save vs poison and disease, +2 to save vs Horror Factor; all in addition to attribute bonuses. Very non-combative: flees unless a rider directs otherwise. A.R. 8 is natural (soft-bodied insect). Color variants: Red +2D6 Spd; Orange or Rusty Brown leaps 8 ft high and 10 ft across, +1 dodge; Brown +1D6+8 S.D.C., +1 save vs poison and disease; Black +20% prowl and half the wing noise; Dark Blue +2 I.Q., +2 initiative; Dark Green goes an extra day or two without food or water; Yellow or Yellow-Green +1 initiative, +25% track by smell, 50% recognize scent. Riding uses Horsemanship: Exotic at -15% unless the rider has empathy or telepathy; untrained insects are a further -15%. Bloated or sick ones fly at half speed and lose all bonuses.', 'Prowl 33%, swim 33%, track by smell 50%. Languages: none.', 'Strong flier that leaps 5 ft, clings to walls and ceilings, cannot be dazzled by bright light, has a keen nose and lasts days without water. Flies 50 mph for one hour per two P.E. points, or 75 mph for one minute per P.E. point, turning and landing anywhere, but its wings are deafeningly loud. Sticky foot pads grip vertical and inverted surfaces; on smooth ones its speed is halved.', 'None', 'None, although it responds very well to empathic and telepathic communication', '6-7 feet (1.8 to 2.1 m) long', 'Approx. 260 pounds (572 kg)', '5 years; full size within 3 months of birth', 'Exclusive to the Baalgor Wastelands, though able to survive in any warm climate', 'None, per se; easily domesticated as riding beasts', 'None, per se; most predators find them bad-tasting', 'None; treated as an animal.', 'Hairless metallic-sheened giant insect, part housefly and part beetle, kept as a one-rider flying mount. Docile but very stupid and disloyal, it is steered by reins alone and wanders off to feed when hungry. A trained adult sells for 1,000 to 1,500 gold, an untrained one for 400-500, an egg for 70-100.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.57-59'),
('sandwyrm-pf', 'Sandwyrm', 'dragon', 'palladium-fantasy', 0, 'Anarchist or evil (any, but usually miscreant or diabolic)', '{"IQ":"1D6+4","ME":"1D6+6","MA":"1D6+6","PS":"6D6+30","PP":"1D6+8","PE":"1D6+22","PB":"1D6","Spd":"2D6+30"}', 'PEx2+100', '1D6x10+100', NULL, '6D6', 'ME+1D6', 'Hit Points (P.E.x2 +100) and S.D.C. (1D6x10+100) are for young and adolescents; multiply by ten for adults. P.P.E. is 6D6 +3D6 per level of experience. I.S.P. is the M.E. number +1D6 per level of experience. P.S. is considered supernatural. Speed is halved when digging or travelling underground. Average level of experience 5-7, on the dragon experience table.', 12, 15, '{"attacks":3,"initiative":1,"strike":2,"parry":2,"pull":1}', 'Stored figures are Hatchling/Young; all are doubled for adults and are in addition to attribute bonuses. Attacks: three by physical or one by magic. Automatic dodge (no melee action used), +2 on all saving throws, +4 to save vs possession, +6 to save vs Horror Factor. Natural A.R. is 12 for Hatchling/Young and 15 for an Adult. Vulnerabilities: rune weapons do double damage; it underestimates opponents and acts in haste or anger. Damage varies with supernatural P.S.', 'Underground skills roughly equal to the three of the Baalizad (+5%), climb 80%/75%, land navigation 80%, track animals 70%, track humanoids 65%, wilderness survival 90%, Gobblely and Dragonese/Elven 75%; track by smell 70% (+15% on a blood trail).', 'Supernatural strength and stamina; burrows; tracks by scent and takes only half the usual penalties when blinded; nightvision 600 ft (183 m); sees the invisible; immune to heat and fire, with magical fire doing a quarter damage; regenerates 6D6 S.D.C./H.P. each melee round. Mouth tentacles reach about 50 ft (15.2 m).', 'Two spells per level of experience from level 1-4 Fire or Earth Warlock spells, mixed freely.', 'Empathy, Presence Sense, Mind Block and 1D4 Sensitive powers of choice.', '300-400 feet (92.4-123.2 m) long, 40-50 feet (12.3-15.4 m) tall', NULL, 'Scholars believe 1000 years to be the maximum', 'Found only in the Baalgor Wastelands; prefers the sandy desert but can turn up in the rocky and mountainous regions. Fewer than 200 are believed to exist; the Eandroth say at least double.', 'A rarity; occasionally other dragons, powerful sorcerers, demon lords, demigods and gods. Rumored ties to the Kingdom of Giants are unsubstantiated.', 'Virtually everything', 'None.', 'Primitive, dim and lazy dragon kin shaped like an immense many-legged serpent, red and gold or tan with deep blue eyes and a tentacled maw. It sleeps under sand for years, ambushes whatever walks overhead, and about 30% keep a lair of trophies.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.59-61'),
('sloderi', 'Sloderi', 'monster', 'palladium-fantasy', 0, 'Anarchist or Miscreant', '{"IQ":"1D6+1","ME":"1D6+6","MA":"2D6","PS":"1D6+16","PP":"1D6+18","PE":"1D6+16","PB":"1D6+4","Spd":"3D6+24"}', 'PE+20', '6D6+6', NULL, '3D6', NULL, 'A pack leader has a bonus 2D6 S.D.C. and +4 to P.S. I.Q. is high animal intelligence.', 6, 10, '{"attacks":4,"initiative":3,"strike":1,"roll":3}', '+3 to roll is with punch, fall or impact. +2 to save vs poison and disease, +2 to save vs Horror Factor; all in addition to attribute bonuses. Horror Factor is 10 for an individual and 13 when facing a group of two or more. Gliding attacks count as a leap attack. A.R. 6 is natural.', 'Track by smell 55% (+30% on a blood scent), land navigation 90%, climb 95%/80%, swim 40%, prowl 70%. Languages: none, per se; barks, grunts and roars.', 'Hawk-sharp sight (a rabbit at two miles), fine hearing and smell, and a prehensile whip tail used for balance and grip. Leaps 6 ft up and 30 ft along from standing, or 25 ft up and 150 across after a full melee round of run-up with a glide. Dropping from a height it glides silently 1000-1200 ft down and as far across.', 'None', 'None', '6-7 feet (1.85-2.15 m) long, with a sleek, thin build', NULL, '10-15 years', 'Baalgor Wastelands, especially the rocky desert, and mountainous parts of the Old Kingdom; occasionally Timiro', 'Only others of their kind', 'Tuskers and Mologoths; humanoids, particularly Eandroth and giants, are enemies and prey', 'None; treated as an animal.', 'Man-sized scaly quadruped with a tyrannosaur head, retractable talons and gliding membranes between its legs. It hunts alone or in packs of 1D4+1, stalking caravans for days and usually fleeing rather than fighting to the death. Trained ones sell for 1,000-2,000 gold in Troker; a mated pair fetches up to 10,000.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.61-63'),
('thin-one', 'Thin One', 'monster', 'palladium-fantasy', 0, 'Diabolic (30%), miscreant (30%), aberrant (10%) or anarchist (25%); best suited as NPC villains', '{"IQ":"3D6+4","ME":"4D6","MA":"4D6","PS":"2D6","PP":"2D6","PE":"2D6","PB":"1D6","Spd":"2D6"}', 'PE+3D6', '3D6+6', NULL, '6D6+25', NULL, 'Can also tap the P.P.E. of its host, and drains one P.P.E. point a day from it. All figures are for the creature in its natural state; inside a host it uses the host''s attributes, skills and abilities and the host body takes all damage.', 8, 9, '{"attacks":2}', 'Two attacks in its natural state, or those of the host body. No bonuses in its natural state, or those of the host. Paralysing touch needs a 16 or higher to save. H.F. 9 applies in its natural state and reads more as curiosity or amazement. Vulnerabilities: dies after more than one hour below 32 degrees Fahrenheit and leaves the host first; a natural 20 on the host has a 01-25% chance of also damaging it, after which it flees the host; psionics that target a mind (Mind Bolt, Hypnotic Suggestion, Mind Bond, Mind Wipe), and psionic and magical illusions, affect it; cold-based magic may draw it out and does double damage outside a host; sense evil and see aura reveal it; exorcism confirms but does not expel it. A freed host has -10% to skills and -2 to strike, parry and dodge for a few days.', 'Scale walls 80%, prowl 50% (+35% in darkness, shadows or hiding and not moving). Languages: a sub-harmonic language of their own; all also appear to speak Elven.', 'Enters a paralysed host through the mouth and runs the body from within, with the host''s mind held in stasis. Paralyses by touch as the Paralysis Bolt spell, never at range. Sees auras constantly at no cost. Folds down to grapefruit size and slips through very narrow gaps.', 'None in their natural state beyond the paralysing touch and the possession itself.', 'None, aside from the natural ability to see aura and detect psionics (range 60 feet/18.3 m; line of vision).', 'Almost 8 feet (2.4 m) tall at full height; folds to the size of a grapefruit', NULL, 'Unknown; believed to be 30-40 years', 'Originally only the Baalgor Wastelands; feared to have spread nearly everywhere except the Great Northern Wilderness, Bizantium, Phi, Lopan and the northern half of the Eastern Territory, which are too cold', 'Thought to associate with certain demons or other powerful supernatural beings; pure theory', 'All humanoids and many larger animals, as potential hosts; psychics are natural enemies', 'None. It uses the O.C.C., skills and experience of its host, frozen at the level the host had when taken, and keeps only dim memories after leaving.', 'Spindly wire-like parasite with hooked limbs and a tiny featureless head that lives on the magical energy of a body it wears. Almost unknown to the world, usually solitary, emotionless and cruel in a host, and its crimes are often blamed on Changelings.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.63-66'),
('vrill', 'Vrill', 'humanoid', 'palladium-fantasy', 1, 'Any, but tend toward good or selfish', '{"IQ":"3D6","ME":"4D6","MA":"3D6","PS":"2D6+2","PP":"3D6","PE":"2D6+2","PB":"3D6","Spd":"3D6"}', 'PE+1D6', '10', NULL, '6D6+10', NULL, 'Hit Points are P.E. plus 1D6 per level. S.D.C. is 10 plus any from physical skills and O.C.C.', 5, 6, '{"attacks":3}', 'Attacks per melee: three, including the extra attack from radar, or by O.C.C. plus the radar attack. No bonuses aside from the radar ability. When using Radar/Sonar: +4 on initiative, +2 to parry and dodge, +3 to strike, +1 attack per melee, and no minuses when blinded or in darkness. Radar is fouled by rain, snow, dust and sandstorms (no bonuses, no extra attack; in darkness or blinded as well, the usual -10 to strike, parry and dodge). Smoke: abilities at -30%, bonuses halved, extra attack kept. Radar does not pass cloth, wood, walls or people. A.R. 5 is natural.', 'Swim 90%. Radar/Sonar: interpreting shapes 50% +5% per level, estimating distance 60% +5% per level, estimating direction 50% +5% per level, estimating speed 40% +4% per level, estimating exact location 40% +4% per level. Languages: Elven, Dwarven and Gobblely at 98%, spoken and written; never better than 10% in any other language.', 'Human-grade senses, natural swimmers able to dive to 600 ft (183 m). Radar/Sonar: senses where things are and how they move out to 400 ft (122 m) +100 ft (30.5 m) per level, most useful in the dark and underwater.', 'By O.C.C.', 'A Vrill with psionics is a psi-mystic or psi-healer; one of any other O.C.C. can not have psionics.', '5 and a half to 6 feet tall (1.6 to 1.8 m)', '160 to 170 lbs (72 to 76.5 kg)', '100 years', 'Most common in the Baalgor Wastelands; reported in the Old Kingdom, especially near Mount Nimro, and in the less populated parts of Timiro and the southern Eastern Territory. Dislikes very moist and cold climates.', 'No official allies; welcomed by Dragonmen, Eandroth, Gosai, Quorians, Quillbacks, and many Orc and Goblin tribes, the last two as healers', 'They consider no people their enemy, though humans and Ogres have persecuted them', '95% are Monk (scholarly, not warrior), Scholar, Ranger, Sailor, Druid, Psi-Healer or Psi-Mystic; most of the other 5% are Warlocks or Clergy. Apart from Ranger and Sailor they usually avoid men at arms classes.', 'Gentle lizard-frog people with spiky khaki-to-beige scales, two fingers and a thumb, and a fin ridge down the back. Nearly wiped out in the Elf-Dwarf War and with no memory of their origin, they roam as healers, explorers and mystics, travel light and shun rune weapons.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.66-68'),
('adraodan-minotaur', 'Adraodan Minotaur', 'humanoid', 'palladium-fantasy', 1, 'Any, but most are good or unprincipled; rarely anarchist or evil', '{"IQ":"2D6+2","ME":"3D6","MA":"2D6+4","PS":"5D6","PP":"4D6","PE":"5D6","PB":"3D6","Spd":"2D6+3"}', 'PE+1D6', '2D4x10', NULL, '4D6', NULL, 'Hit Points are standard: P.E. plus 1D6 per level. S.D.C. is 2D4x10 plus those gained from O.C.C.s and physical skills (2D6x100 on Rifts Earth, every 100 S.D.C. equal to one M.D.C.). I.S.P. depends on the O.C.C.; a Crusader of Light starts with M.E. plus 1D6+2 per level of experience.', 12, 14, '{"initiative":1,"strike":1,"parry":1,"dodge":1,"pull":2}', '+3 to save vs Horror Factor; all in addition to attribute and skill bonuses. No attacks per melee line is printed in this block. Natural A.R. 12; body armor may be worn as well. Horn charge has a 60% chance of knocking the victim down (loses one melee attack and initiative). Eyes are light sensitive: in daylight they see about half as well and half as far as a human. A Crusader of Light is a major psychic who needs 12 or higher to save vs psionics. Average level of experience: all start at 1st or 2nd.', 'Recognize scent 22%, track by blood scent 54%. Speak Troll/Giantese, Gobblely and Elven; all are literate in Elven (+20%).', 'The usual Minotaur strength, stamina and keen nose, with fire and cold doing half damage. Ages below ground stretched their nightvision to 600 ft (183 m), working in total darkness, at the cost of poor daylight sight.', 'None for the Adraodan.', 'All have at least major psionics; fewer than half a percent are Mind Mages.', '7.6 to 9 feet (2.3 to 2.7 m) tall', '400 to 650 pounds (180 to 292 kg)', '400 years, few live past 500', 'Mostly in and around the Baalgor Wastelands, Old Kingdom and Eastern Territory for years to come', 'The forces of good', 'The forces of evil, particularly the Kkairojan Minotaurs', 'Crusader of Light 30%, Psychic Sensitive 25%, Psi-Healer 23%, Psi-Mystic 10%. The Crusader is the tribe''s own class: a Knight who trades Horsemanship, Heraldry, W.P. Lance and two related skills for seven Sensitive or Physical psionic powers. The other 12% choose among Bard, Minstrel, Scholar, Priest (of Light), either Monk (Scholastic or Warrior), and the Men of Arms classes Ranger, Palladin, Mariner, Sailor and Juggler. No magic class but Psi-Mystic.', 'One of three Minotaur tribes sealed beneath the Sandy Desert for some 70,000 years, 2,724 strong, paler and slighter than their surface kin. They renounced the Old Ones, became psychic and idealistic, and now mean to spread across the world as champions of good.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.142-143'),
('kkairojan-minotaur', 'Kkairojan Minotaur', 'humanoid', 'palladium-fantasy', 1, 'Evil, mainly diabolic (63%), miscreant (35%), and 2% aberrant and anarchist', '{"IQ":"2D6+1","ME":"3D6","MA":"3D6","PS":"5D6","PP":"4D6","PE":"5D6","PB":"3D6","Spd":"3D6"}', 'PE+13+1D6', '2D4x10', NULL, '4D6', NULL, 'Attributes are printed here only as ''unchanged, same as all Minotaurs''; the dice stored are those of this book''s Minotaur entry on p.50. Hit Points (modified) are P.E.+13, +1D6 per level of experience. S.D.C. is 2D4x10 plus those gained from O.C.C.s and physical skills. A Soldier of Darkness, Harbinger of Chaos adds 1D6x10+30 Hit Points (or 1D6x10+10 M.D.C. in a Mega-Damage setting) and has P.E.x2 +2D6 P.P.E. per level of experience.', 12, 14, NULL, 'No bonuses or attacks per melee are printed for the base tribesman. Damage Notes: same as all Minotaurs (see this book''s Minotaur entry, p.50); nothing is printed here. Natural A.R. 12; body armor may be worn as well. Soldier of Darkness, Harbinger of Chaos only: natural A.R. 15, +1 extra attack per melee round, +2 on initiative, +1 to strike, +3 to save vs Horror Factor, +1 to Horror Factor, and P.S. becomes supernatural, all in addition to the usual Minotaur, attribute and skill bonuses. Eyes are light sensitive: in daylight they see about half as well and half as far as a human. Average level of experience: 1st to 4th.', 'Recognize scent 40%, track by blood scent 74%. Speak Troll/Giantese, Gobblely and Elven; all are literate in Elven (+10%).', 'The usual Minotaur strength, stamina and keen nose, with fire and cold doing half damage. Ages below ground stretched their nightvision to 600 ft (183 m), working in total darkness, at the cost of poor daylight sight. All are man-eaters and cannibals.', 'Via a Witch-like pact with the Old Ones or a rare magic O.C.C. selection. Soldier of Darkness spells: Sense Evil, Turn Dead, See Wards, Sense Traps, Energy Bolt, Fire Fist, Blind, Agony, Size of the Behemoth, Armor of Ithan, plus one level 1-4 Wizard spell of choice at every other level of experience (2, 4, 6, 8 and so on).', 'Standard, same as humans.', '8 to 9.6 feet (2.4 to 2.8 m) tall', '400 to 700 pounds (180 to 315 kg)', '400 years, few live past 500', 'Most will be found in the Baalgor Wastelands, Old Kingdom, Western Empire, Yin-Sloth Jungles and Land of the South Winds', 'The forces of evil, including demons', 'The forces of good, particularly the Adraodan Minotaurs', 'About a third are Disciples of the Old Ones (the Minotaur Witch class detailed in Old Ones, 2nd Edition). About a third are Soldiers of Darkness, Harbingers of Chaos, a new pact-warrior class given only to this tribe. The remaining third pick from seven classes: Scholar, Wizard, Witch, Necromancer, Thief, Assassin and Priest of Darkness.', 'One of three Minotaur tribes sealed beneath the Sandy Desert for some 70,000 years, 1300 strong, pale and slighter than surface kin. They gave up repentance, serve the Old Ones, and are dispersing in small bands to found cults and seek a way to wake their masters.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.144');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('jaheris-scarbone', 'Jaheris Scarbone', NULL, 'Captain of the Scarbone Crew, and Lord of Scarbone''s Hollow', 'palladium-fantasy', 'Human', '7th level Pirate', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":15,"ME":14,"MA":19,"PS":17,"PP":18,"PE":15,"PB":8,"Spd":11}', 45, 31, NULL, NULL, NULL, 15, NULL, '{"attacks":6,"strike":4,"parry":7,"dodge":7,"damage":2,"roll":2,"pull":3}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall. Critical strike on a natural 18-20. M.A. 19 gives 55% charm/intimidate. P.B. was 13 before his scars. A.R. 15 is his Magical Leather of Iron (214 S.D.C.).', NULL, 'Hand to Hand: Expert and Boxing (Leg Hook); W.P. Sword (+3 strike and parry, +1 throw), W.P. Knife (+3 strike, parry and throw), W.P. Blunt (+3 strike and parry, +1 throw), W.P. Grappling Hook (+2 strike or entangle), W.P. Paired Weapons.', NULL, 'Ring of Loholla (333 P.P.E., permanent but not replenishable; up to six castings a day in any mix): Seal, Magic Pigeon, Words of Truth, Eyes of Thoth, Create Bread and Milk, Heal Self.', NULL, NULL, NULL, 'Glarigel, an indestructible magical long sword (lightning 3D6+6 and fireballs 3D6+2, three times a day each); a pair of silver daggers; three Chaser Crystals, kept for dire emergencies; Magical Leather of Iron (A.R. 15, S.D.C. 214); the Ring of Loholla; a small arsenal of ordinary weapons in his quarters. Commands the Sea Rat, a Timiro Viscount.', '123,442 gold in assorted coin, a ruby worth 43,000 gold, and a velvet bag of 100 diamonds worth 10,000 each', 'Cowardly and cruel. Holds his fleet through fear and keeps his lieutenants busy competing so that none can unseat him.', 'The Scarbone Crew; lieutenants Tsirkan, Agrami, Manaash, Argullud Zugon and Gakrung the Widowmaker', 'Western Empire, which offers 100,000 gold for him alive or dead; pirate hunters', 'Pirate ruler of Scarbone''s Hollow, the westernmost cove on the Baalgor coast, and commander of a fleet of coastal raiders that has already sunk three fleets sent to collect the bounty on him.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.76-77'),
('tsirkan', 'Tsirkan', NULL, 'Lieutenant of the Scarbone Crew and Lead Enforcer', 'palladium-fantasy', NULL, '6th level Pirate', 6, 'Aberrant', NULL, NULL, NULL, '{"IQ":11,"ME":8,"MA":13,"PS":15,"PP":19,"PE":18,"PB":19,"Spd":15}', 45, 19, NULL, NULL, NULL, 13, NULL, '{"attacks":6,"strike":4,"parry":5,"dodge":5,"roll":3,"pull":2}', 'Printed bonuses include attribute bonuses; the line prints +3 to roll with punch or fall and also a second, bare +2 to roll. Critical strike on a natural 18-20. P.E. 18 gives +6% vs coma/death and +2 to save vs magic. P.B. 19 gives 45% charm/impress. A.R. 13 is his studded leather (44 S.D.C.).', NULL, 'Hand to Hand: Expert; W.P. Sword (+3 strike and parry, +1 throw), W.P. Targeting (+3 strike with thrown weapons), W.P. Blunt (+3 strike and parry, +1 throw), W.P. Grappling Hook (+2 strike or entangle).', NULL, NULL, NULL, NULL, NULL, 'Dwarven cutlass (2D4+4, +2 parry) carrying one dose of Dragon''s Breath poison; five darts on each wrist coated with Scorpion''s Blood poison; studded leather armor (A.R. 13, S.D.C. 44); Magic Bandages; Cherubot Rope. Commands the Black Shark, a Byzantium Corsair.', '200 gold', 'A lifelong pirate and compulsive gambler who shakes down unpopular members of the fleet when ashore.', 'Captain Jaheris', 'Agrami, who plots to assassinate him', 'Coastal raider''s son who rose from cabin boy to lieutenant of the Scarbone Crew, where he runs what passes for law at the Hollow.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.77'),
('agrami', 'Agrami', NULL, 'Lieutenant of the Scarbone Crew', 'palladium-fantasy', NULL, '6th level Yin-Sloth Headhunter', 6, 'Miscreant', NULL, NULL, NULL, '{"IQ":9,"ME":11,"MA":14,"PS":18,"PP":23,"PE":17,"PB":10,"Spd":10}', 35, 26, NULL, NULL, NULL, NULL, NULL, '{"attacks":5,"strike":6,"parry":7,"dodge":7,"damage":3,"initiative":1,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall. Critical strike on a natural 18-20. P.E. 17 gives +5% vs coma and death and +1 to save vs magic. Wears no armor.', NULL, 'Hand to Hand: Expert; W.P. Sword (+3 strike and parry, +1 throw), W.P. Knife (+3 strike, parry and throw), W.P. Blunt (+3 strike and parry, +1 throw), W.P. Grappling Hook (+2 strike or entangle), W.P. Paired Weapons.', NULL, NULL, NULL, NULL, NULL, 'A pair of enchanted Mongwanga, heavy multi-bladed throwing knives that never dull and come back when thrown (1D10+3 each, before his own bonuses). No armor and no other magic items. Commands the Razorhead, an old-style Western Carrack rebuilt to be 25% faster with 50% more S.D.C.', '44,500 gold, left in a strongbox at the Hollow where Jaheris has already stolen it', 'Brave, ambitious and easily fooled. Goes into battle bare-chested and schemes to kill Tsirkan as a step toward taking the fleet.', 'The Scarbone Crew', 'Tsirkan; Jaheris, his chief rival', 'Headhunter out of the Yin-Sloth Jungles who signed on with the Scarbone fleet years ago and is now its second-in-command.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.78'),
('manaash', 'Manaash', NULL, 'Lieutenant of the Scarbone Crew', 'palladium-fantasy', 'Ogre', '5th level Mercenary', 5, 'Diabolic', NULL, NULL, NULL, '{"IQ":15,"ME":15,"MA":15,"PS":18,"PP":20,"PE":18,"PB":15,"Spd":15}', 42, 40, NULL, NULL, NULL, 14, NULL, '{"attacks":6,"strike":4,"parry":5,"dodge":5,"damage":4,"roll":3,"pull":3}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall/impact. The +4 is printed as damage/disarm. P.E. 18 gives +6% vs coma/death and +2 to save vs magic. A.R. 14 is his chain mail (44 S.D.C.). The Magic Items line spells his name Manassh.', NULL, 'Hand to Hand: Basic; W.P. Sword (+2 strike and parry, +1 throw), W.P. Blunt (+2 strike and parry, +1 throw), W.P. Chain (+2 strike, +1 parry), W.P. Shield (+2 parry, +1 strike).', NULL, NULL, NULL, NULL, NULL, 'Giant-sized cutlass (2D4+1D6); giant-sized ball and chain (4D6); a pair of Dragon Claws (6D6), his favorite weapons; chain mail (A.R. 14, S.D.C. 44), worn at sea against advice. Commands the You and What Army?, a Byzantium Corsair.', '10,000 in gold and 20,000 in emeralds', 'Cares more for slaughter and burning ships than for loot, so his crew strips a prize quickly before he sets it alight.', 'Captain Jaheris; his own crew, who are devoted to him', NULL, 'Ogre mercenary who fell into piracy by accident and stayed. No captain in the Scarbone fleet inspires his men more.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.78'),
('argullud-zugon', 'Argullud Zugon', NULL, 'Lieutenant of the Scarbone Crew', 'palladium-fantasy', NULL, '3rd level Pirate', 3, 'Anarchist', NULL, NULL, NULL, '{"IQ":13,"ME":10,"MA":13,"PS":21,"PP":21,"PE":21,"PB":10,"Spd":18}', 27, 20, NULL, NULL, NULL, 18, NULL, '{"attacks":4,"strike":5,"parry":6,"dodge":6,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall/impact. No damage total is on the bonus line; the attribute line gives P.S. 21 as +6 to damage. P.E. 21 gives +12% vs coma/death and +3 to save vs magic. A.R. 18 is his Fyr-Kree plate (200 S.D.C.).', NULL, 'Hand to Hand: Expert; W.P. Sword (+2 strike, +1 parry), W.P. Knife (+1 strike, +2 parry and throw), W.P. Blunt (+2 strike and parry), W.P. Grappling Hook (+1 strike or entangle).', NULL, 'Ring of Fleet Feet (10 minutes, three times daily); ring of Multiple Image (20 minutes, twice daily).', NULL, NULL, NULL, 'Flaming sword (6D6) whose flame has been recolored bright blue; plate armor made from the shell of a Fyr-Kree insectoid of the Yin-Sloth Jungles (A.R. 18, S.D.C. 200), light enough to carry no heavy-armor heat penalty; the two rings. Commands the Good As Gold, a Byzantium Brigantine.', '25,000 gold in a safebox at the Hollow, 35,000 in gold and gems in his cabin, and 100,000 gold hidden in the Free City of Troker', 'Shrewd and increasingly greedy; the greed is expected to ruin him.', 'Captain Jaheris', NULL, 'Rising captain of the Scarbone fleet who has taken over a dozen ships in a single year under Jaheris and is envied for his magic and his wealth.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.78-79'),
('gakrung-the-widowmaker', 'Gakrung the Widowmaker', NULL, 'Lieutenant of the Scarbone Crew', 'palladium-fantasy', 'Orc', '4th level Pirate', 4, 'Diabolic', NULL, NULL, NULL, '{"IQ":13,"ME":10,"MA":22,"PS":20,"PP":14,"PE":15,"PB":3,"Spd":7}', 33, 30, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"damage":5,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. +2 to roll with punch or fall and, printed separately, +2 to roll with impact. M.A. 22 gives 70%, to intimidate only. A.R. 13 is her studded leather (38 S.D.C.). No Hand to Hand style is printed.', NULL, 'W.P. Sword (+2 strike and parry, +1 throw), W.P. Battle Axe (+2 strike and parry, +1D6 damage), W.P. Blunt (+2 strike and parry), W.P. Grappling Hook (+1 strike or entangle).', NULL, NULL, NULL, NULL, NULL, 'Giant-sized battle axe (3D6) that glows red within 100 ft of an elf and then adds 1D6 heat damage (4D6 total); studded leather (A.R. 13, S.D.C. 38); a case of rare Western brandy worth 12,000 gold. No magic items beyond the axe.', '4,397 gold in her cabin', 'Clever and murderous. Kills crewmen over a wrong look; those who last a few months with her become fiercely loyal.', 'Captain Jaheris; her long-serving crew', NULL, 'Female orc captain, reckoned the most vicious killer in the whole Scarbone fleet.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.79'),
('graven-killjoy', 'Graven Killjoy', NULL, 'Pirate Lord of Buccaneer''s Junction', 'palladium-fantasy', 'Human', '8th level Pirate', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":14,"ME":9,"MA":11,"PS":17,"PP":20,"PE":16,"PB":8,"Spd":17}', 41, 30, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":6,"parry":7,"dodge":7,"initiative":1}', 'Printed bonuses include attribute bonuses. +2 to disarm, +3 to save vs Horror Factor. The line runs ''+7 parry and dodge, and roll with punch/fall/impact'', so the roll bonus may also be +7; it is left out of the combat block. No damage total on the bonus line; the attribute line gives P.S. 17 as +2 to damage. P.E. 16 gives +4% vs coma/death and +1 to save vs magic. Critical strike on 18-20; leap attack is a critical. No penalty for his missing right eye. A.R. 13 is his chain mail (219 S.D.C.).', NULL, 'Hand to Hand: Martial Arts (all jump kicks, backward sweep, tripping/leg hook); W.P. Sword (+3 strike and parry, +2 throw), W.P. Knife (+3 strike and parry, +4 throw), W.P. Blunt (+3 strike and parry, +1 throw), W.P. Grappling Hook (+2 strike and entangle, no parry possible), W.P. Paired Weapons.', NULL, 'Familiar Link, cast for him by a wizard of Troker.', NULL, NULL, NULL, 'Bonecutter, a long sword (1D8+1D6+5 total; +9 strike and parry, +8 throw; indestructible, eternally sharp); Bloodthorn, a dagger (2D6+1 total; +9 strike and parry, +10 throw; returns when thrown and ignores A.R.); a ragged coat of magically weightless, noiseless chain mail (A.R. 13, S.D.C. 219); a Gem of Direction; five Screech Bottles. Commands the Fist of Utu, a Western war galley.', '71,409 gold in mixed coin, an opal worth 2,000, 3 pearls worth 1,000 gold each and 10 pearls worth 500 gold each', 'Ruthless and capable. Took the Junction by murder, and lesser pirates now plot to do the same to him.', 'Fellow pirate lords Jammer, Shade and Mojo, none of whom he trusts. Familiar: a booted eagle (25 hit points, three attacks per melee, talons 2D6+2, bite/peck 2D4, +2 initiative, +4 strike, +4 dodge) that he also sends out to scout for ships.', 'Friends of Captain Oslof Grunngeld, the popular ogre leader he murdered; ambitious low-ranking pirates', 'Young one-eyed human, newest of the four pirate lords who govern Buccaneer''s Junction. He wears a patch over the right eye he lost in a duel.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.80-81'),
('jammer', 'Jammer', NULL, 'Pirate Lord of Buccaneer''s Junction', 'palladium-fantasy', 'Dogre', '7th level Pirate', 7, 'Diabolic', NULL, NULL, NULL, '{"IQ":6,"ME":4,"MA":8,"PS":27,"PP":20,"PE":23,"PB":3,"Spd":10}', 49, 40, NULL, NULL, NULL, NULL, 12, '{"attacks":5,"strike":6,"parry":7,"dodge":6,"damage":12,"roll":6,"pull":2}', 'Printed bonuses include attribute bonuses. The roll bonus is printed as roll with impact. +10% vs coma/death, +3 to save vs magic and poison, +2 to save vs Horror Factor. Critical strike on 18-20. Blood Lust (berserk rage, common in combat): a further +4 strike, +10 damage, +8 to save vs Horror Factor and two more attacks per melee, ignoring pain and fatigue, but -3 initiative, -4 parry and he will not dodge; he attacks anyone nearby, crew included. Wears no armor.', NULL, 'Hand to Hand: Expert, paired weapons; W.P. Chain (+2 strike, +1 parry), W.P. Siege Weapons (+2 strike), W.P. Blunt (+2 strike and parry, +1 throw), W.P. Grappling Hook (+2 strike and entangle, no parry possible).', 'Clawed hands and a damaging bite. Prone, as all Dogres are, to a killing frenzy brought on by anger or frustration, during which fear and pain mean nothing to him.', NULL, NULL, NULL, NULL, 'Wyrmbane, a giant-sized magic Hercules club (6D6+12 total in his hands; +8 strike, +9 parry, +7 throw; double damage to dragons; Thunder hammer adds 2D6 and a thunderclap on each hit). No armor and no other magic items. Commands the Big Ship, a Byzantium behemoth.', '84,000 in gold, gems and jewelry in a safe at the Junction by his purser''s books; the true figure should be about three times that', 'Fearless, rash and impossible to control. Thinks himself unkillable and never backs out of a fight, which makes him simple to bait.', 'His crew, who adore him and earn double shares; Pareaux Veddish, his second-in-command and bookkeeper, who is robbing him', 'Western Empire (25,000 gold reward); the other three pirate lords, who talk of handing him in for it', 'Dogre pirate lord of Buccaneer''s Junction, as dangerous to his allies as to his foes. The other lords expect him to die at sea before long.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.81'),
('shade-pirate-lord', 'Shade', NULL, 'Pirate Lord of Buccaneer''s Junction', 'palladium-fantasy', 'Elf', '7th level Assassin', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":18,"ME":15,"MA":8,"PS":18,"PP":18,"PE":15,"PB":24,"Spd":13}', 49, 31, NULL, NULL, NULL, 12, NULL, '{"attacks":7,"strike":4,"parry":10,"dodge":8,"damage":7,"initiative":1,"roll":4,"pull":3}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall/impact. +4% to all skills, +4 to disarm, +6% vs coma/death, +2 to save vs magic, +2 to save vs poison, 70% charm/impress. Automatic knockout/stun on a natural 17-20. A.R. 12 is a natural A.R. conferred by a magic ring; he wears no armor.', NULL, 'Hand to Hand: Assassin and Boxing; W.P. Sword (+3 strike and parry, +1 throw), W.P. Knife (+3 strike, parry and throw), W.P. Spear (+3 strike and parry, +2 throw), W.P. Archery (range +80 feet, rate of fire 6, +3 strike, +1 parry).', NULL, 'Purse clasp warded with Inflict: Death (2D4x10 damage to anyone but him who touches it).', NULL, NULL, NULL, 'Magic short spear with twin parallel blades (2D6+10; +6 strike, +4 parry; extra damage die and eternally sharp); two Cyclops Lightning arrows; long sword, four daggers, crossbow with 20 bolts, bullwhip; ring granting natural A.R. 12; a ''bag of tricks'' holding four smoke bombs, two stink bombs, two roman candles and two flash bombs (each flash bomb works as a first-level Blinding Flash). Commands the In Darkest Night, a newly captured Byzantium schooner, and still owns the Styphon''s Blood, a worn Western Merchantman.', '225,000 in gold, all but 5,000 of it changed into Old Kingdom Dragon Coins and carried in a warded black leather belt purse', 'Fastidious and aloof. Finds piracy and pirates distasteful and is only saving until he can retire somewhere cultured, such as the Western Empire or Timiro.', 'Fellow pirate lords Graven Killjoy, Jammer and Mojo', NULL, 'Elven assassin who drifted into piracy without meaning to and became one of the four lords of Buccaneer''s Junction.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.81-82'),
('mojo-pirate-lord', 'Mojo', NULL, 'Pirate Lord of Buccaneer''s Junction', 'palladium-fantasy', NULL, '4th level Wizard', 4, 'Miscreant', NULL, NULL, NULL, '{"IQ":17,"ME":19,"MA":15,"PS":10,"PP":9,"PE":9,"PB":11,"Spd":13}', 24, 20, NULL, NULL, NULL, 10, NULL, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall/impact. +3% to all skills, +2 to save vs psionic attack and insanity. A.R. 10 is his soft leather (20 S.D.C.).', NULL, 'Hand to Hand: Basic; W.P. Staff (+2 strike, +1 parry).', NULL, 'Spells known: Decipher Magic, Sense Magic, Cloud of Slumber, Globe of Daylight, Tongues, Enchanted Cauldron, Death Trance, See the Invisible, Thunderclap, Mystic Alarm, Turn Dead, Armor of Ithan, Energy Field, Telekinesis, Swim as a Fish, Energy Bolt. Scroll pages only (not yet learned): Plasma Bolt, Teleport: Minor, Create Zombie, Magic Pigeon, Invulnerability: Limited.', NULL, NULL, NULL, 'Iron staff (2D6); pair of silver plated daggers (1D6); soft leather armor (A.R. 10, S.D.C. 20); a large Book of Spells with a laced spine and silver-runed, indestructible pages, holding one scroll of every spell he knows plus five he has not learned. Commands the Sorcerous Ways, a Western merchantman, the poorest ship in the fleet.', 'Ward components worth 55,000 gold, plus 2,500 gold in cash', 'Drunk on his new power and sure he is destined to be a feared sorcerer-pirate. Wants to become a Diabolist and to trade up to a better ship.', 'Fellow pirate lords Graven Killjoy, Jammer and Shade', NULL, 'Wizard taken prisoner by pirates on the Sea of Scarlet Waters who joined them, led a mutiny and took the captain''s place. Now one of the four lords of Buccaneer''s Junction.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.82'),
('konilock-of-the-flame', 'Konilock of the Flame', NULL, 'Elemental Lord of the Baalgor Coast', 'palladium-fantasy', 'Human', '8th level Fire Warlock', 8, 'Diabolic', NULL, NULL, NULL, '{"IQ":24,"ME":21,"MA":21,"PS":14,"PP":12,"PE":12,"PB":6,"Spd":11}', 34, 25, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":1,"parry":2,"dodge":2,"damage":2,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. Attacks per melee: 5 physical or two by magic. Roll bonus is with punch/fall/impact. +10% to all skills, +3 to save vs psionic attack, +4 to save vs insanity, 65% trust/intimidate. Critical strike 19-20. Other elemental abilities are deferred to pages 108-112 of the Palladium Fantasy RPG, 2nd Edition. A.R. 13 is his studded leather (38 S.D.C.).', NULL, 'Hand to Hand: Basic (body flip/throw); W.P. Staff (+3 strike and parry, +1 throw), W.P. Sword (+3 strike and parry, +2 throw).', NULL, 'Cloud of Smoke, Globe of Daylight, Impervious to Fire, Cloud of Ash, Cloud of Steam, Fuel Flame, Flame Lick, Tongue of Flame, Darkness, Circle of Cold, Circle of Flame, Screaming Wall of Fire, Extinguish Fire, Fire Ball, Flame Friend, Heal Burns, Blue Flame, Wall of Ice, Dancing Fires, Eternal Flame, Fire Whip, 10 foot Wheel of Fire, Burst into Flame, Plasma Bolt.', NULL, NULL, NULL, 'Dwarven falchion (+4 damage, +2 strike and parry; totals +6 strike, +7 parry, +2 throw, 2D6+6 damage); studded leather (A.R. 13, S.D.C. 38). No magic items. Shares command of the Power of Four, a Byzantium behemoth shaped like a giant fish.', '15,000 gold in cash and nothing else of note; the crew''s takings were shared out recently and the rest went on the grotto and wages', 'Devious, efficient and cruel. Takes charge although the four are nominally equals, never knowingly lets a victim live, and has toyed with turning the crew into a mercenary company.', 'Byzantium Freck, Leslo Squibbs and Seremm the Gray; the Sea-Dogs of the Elements', NULL, 'Burn-scarred fire warlock and real leader of the four warlocks who run the Cove of Elemental Evil and its pirate crew.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.83'),
('byzantium-freck', 'Byzantium Freck', NULL, 'Elemental Lord of the Baalgor Coast', 'palladium-fantasy', 'Human', '8th level Air Warlock', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":15,"ME":10,"MA":7,"PS":18,"PP":17,"PE":17,"PB":13,"Spd":13}', 42, 30, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"damage":5,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. Attacks per melee: 5 physical attacks or two spell attacks. Roll bonus is with punch/fall/impact. Critical strike 19-20. Other elemental abilities are deferred to pages 108-112 of the Palladium Fantasy RPG, 2nd Edition. A.R. 13 is his studded leather (38 S.D.C.).', NULL, 'Hand to Hand: Basic (body flip/throw); W.P. Staff (+3 strike and parry, +1 throw), W.P. Chain (+3 strike, +2 parry).', NULL, 'Breathe Without Air, Cloud of Slumber, Create Light, Create Mild Wind, Stop Wind, Change Wind Direction, Miasma, Silence, Call Lightning, Float in Air, Wind Rush, Ball Lightning, Calm Storm, Phantom Footman, Protection From Lightning, Breath of Life, Detect the Invisible, Phantom, Whirlwind, Electrical Field, Mist of Death, Atmospheric Manipulation, Wind Blast, Snow Storm.', NULL, NULL, NULL, 'Ball and chain (+5 strike and parry, 3D6+5); nunchaku (+5 strike and parry, 2D4+5); bullwhip (2D6+5); studded leather (A.R. 13, S.D.C. 38). No magic items.', '15,000 gold, on the same terms as Konilock', 'Egomaniac with a loose grip on reality: he holds that the Island Kingdom of Byzantium is named for him and is his by right. Otherwise a keen and bloodthirsty pirate who does whatever Konilock says.', 'Konilock of the Flame, Leslo Squibbs and Seremm the Gray', NULL, 'Air warlock and able fighter, one of the four warlock lords of the Cove of Elemental Evil.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.84'),
('leslo-squibbs', 'Leslo Squibbs', NULL, 'Elemental Lord of the Baalgor Coast', 'palladium-fantasy', 'Human', '8th level Water Warlock', 8, 'Diabolic', NULL, NULL, NULL, '{"IQ":10,"ME":10,"MA":10,"PS":10,"PP":10,"PE":10,"PB":10,"Spd":10}', 45, 20, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":1,"parry":2,"dodge":2,"damage":2,"roll":2,"pull":2}', 'Attacks per melee: 5 physical attacks or two spell attacks. Roll bonus is with punch/fall or impact. Critical strike on 19-20. The book prints every attribute as 10. Other elemental abilities are deferred to pages 108-112 of the Palladium Fantasy RPG, 2nd Edition. A.R. 13 is his studded leather (38 S.D.C.).', NULL, 'Hand to Hand: Basic (body flip/throw); W.P. Sword (+3 strike and parry, +2 throw), W.P. Shield (+2 strike, +3 parry); these include attribute bonuses.', NULL, 'Create Fog, Dowsing, Purple Mist, Walk the Waves, Water to Wine, Breathe Underwater, Impervious to Ocean Depths, Change Current, Ride the Waves, Command Fish, Sheet of Ice, Create Water, Hail, Water Wisps, Protection from Lightning, Snow Storm, Whirlpool, Little Ice Monster, Ten Foot Ball of Ice, Part Waters, Summon and Control Storm, Creatures of the Waves, Calm Waters (superior 8th level spell), Summon Sharks or Whales.', NULL, NULL, NULL, 'Dwarven long sword (+3 damage, +3 parry; totals +4 strike, +8 parry, +2 throw, 2D6+7 damage); small iron shield (S.D.C. 50; totals +3 strike, +5 parry); studded leather (A.R. 13, S.D.C. 38). No magic items.', '15,000 gold, with another 6,000 hidden in a secret place', 'Angry and erratic. Feels slighted beside the others'' showier magic, so he takes reckless chances and stirs up the crew; two of his partners are thinking of replacing him.', 'Konilock of the Flame, Byzantium Freck and Seremm the Gray, for now', NULL, 'Water warlock among the four lords of the Cove of Elemental Evil, arguably the strongest of them at sea, where his ice and cold magic is most startling.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.84'),
('seremm-the-gray', 'Seremm the Gray', NULL, 'Elemental Lord of the Baalgor Coast', 'palladium-fantasy', NULL, '7th level Earth Warlock', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":12,"ME":11,"MA":17,"PS":20,"PP":13,"PE":12,"PB":13,"Spd":15}', 53, 24, NULL, NULL, NULL, 13, NULL, '{"attacks":5,"strike":1,"parry":2,"dodge":2,"damage":7,"roll":2,"pull":2}', 'Attacks per melee: 5 physical attacks or two spell attacks. Roll bonus is with punch/fall or impact. Critical strike on 19-20. Other elemental abilities are deferred to pages 108-112 of the Palladium Fantasy RPG, 2nd Edition. A.R. 13 is his studded leather (38 S.D.C.).', NULL, 'Hand to Hand: Basic (body flip/throw); W.P. Staff (+3 strike, +2 parry and throw), W.P. Shield (+2 strike, +3 parry); these include attribute bonuses.', NULL, 'Chameleon, Dowsing, Fool''s Gold, Rot Wood, Create Dirt or Clay, Hopping Stones, Crumble Stone, Dig, Encase Object in Stone, Locate Minerals, Wall of Stone, Animate Object, Mend Stone, Rust, Sand Storm, Little Mud Mound, Travel Through Stone, Clay or Stone to Iron, Mend Metal, Metal to Clay, Petrification.', NULL, NULL, NULL, 'Indestructible magical wooden staff that spits lightning bolts (3D6+6, 40 ft/12 m range) three times a day; silver dagger; silver cross; cutlass; small iron shield (S.D.C. 50; totals +3 strike, +5 parry); studded leather (A.R. 13, S.D.C. 38); Crystal of True Seeing.', '15,000 gold, on much the same terms as Konilock', 'Quiet, steady and shrewd. Tired of his partners'' pettiness and ill at ease on the water, he would not object to leaving.', 'Konilock of the Flame, Byzantium Freck and Leslo Squibbs', NULL, 'Earth warlock, the most level-headed of the four lords of the Cove of Elemental Evil. He wanted a Byzantium Stone Ship for the crew and was overruled.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.84-85'),
('azamon-redlin', 'Azamon Redlin', NULL, 'The Duke of Redlin', 'palladium-fantasy', NULL, '10th level Noble and self-styled pirate', 10, 'Aberrant', NULL, NULL, NULL, '{"IQ":13,"ME":12,"MA":19,"PS":17,"PP":18,"PE":17,"PB":20,"Spd":9}', 53, 40, NULL, NULL, NULL, 15, NULL, '{"attacks":6,"strike":4,"parry":5,"dodge":5,"damage":5,"roll":2,"pull":4}', 'Printed bonuses include attribute bonuses. Roll bonus is with punch/fall/impact. +5% vs coma/death, +1 to save vs magic/poison, 50% charm/impress. Critical strike 18-20. A.R. 15 is his magic plate and chain (100 S.D.C.).', NULL, 'Hand to Hand: Martial Arts (body flip/throw); W.P. Sword (+4 strike and parry, +2 throw), W.P. Knife (+4 strike and parry, +5 throw), W.P. Paired Weapons.', NULL, 'Signet ring of dragon bone bearing wards of Inflict: Cold, Mystic Energy Drain, Permanence and others unidentified; it keeps its wearer comfortably cool at all times and works for anyone who puts it on.', NULL, NULL, NULL, 'Flaming sword (6D6) and flaming dagger (4D6, returns when thrown), used together; an ornamental dagger that is the badge of House Redlin, drawn only in dire need; magically weightless and noiseless plate and chain (A.R. 15, S.D.C. 100); the dragon-bone signet ring. His manor''s furnishings are worth millions, among them a tapestry (35,000 gold), a silver urn holding his grandfather''s ashes (12,000) and a set of emeralds (25,000 in all).', '45,000 gold in a locked and warded strongbox in his manor', 'Vengeful, self-indulgent and proud. Hunts ships of the Empire and of the noble families he blames for his House''s fall, and plays king over his cove.', 'Vorgoth Dur (diabolic human anti-paladin), Glimmig Bogras (aberrant Priest of Darkness, High Initiate of the Cult of Set), Skorde Bi''giriith (miscreant Diabolist); his crew and taskmasters; other pirates of the region, who fence and carry word for him', 'Western Empire: Emperor Itomas has set 250,000 gold on him, preferably alive. Pirate-hunters Idimir Vass, Neshueh Ghenna and Sir Runneer Shaw', 'Last heir of a Western noble house ruined in the Empire''s civil war, turned pirate. He rules Cove Redlin from a manor inside a walled keep, with a slave-worked plantation beside it.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.85-86'),
('king-kai-the-wanderer', 'King Kai the Wanderer', NULL, 'Warrior King of the Free City of Troker', 'palladium-fantasy', 'Ogre', '9th level Knight', 9, 'Aberrant', NULL, NULL, NULL, '{"IQ":14,"ME":12,"MA":17,"PS":25,"PP":21,"PE":25,"PB":9,"Spd":20}', 65, 40, NULL, NULL, NULL, 15, NULL, '{"attacks":7,"strike":5,"parry":8,"dodge":8,"damage":10,"initiative":1,"roll":4}', 'The line reads ''+4 to roll, +5 to strike, pull punch, +8 to parry and dodge'', so pull punch has no clear number of its own (possibly +5) and is left out of the combat block. +2 to disarm, +2 vs Horror Factor. KO on a natural 20 (Boxing); leap attack is a critical strike. Spd is 40 with his Dwarven combat boots. W.P. Lance is deferred to the Knight O.C.C. A.R. 15 is his magical plate and chain (200 S.D.C., regenerating 10 per hour).', NULL, 'Hand to Hand: Martial Arts and Boxing (tripping/leg hook, leap attack); W.P. Paired Weapons, W.P. Sword (+4 strike, +3 parry, +2 throw), W.P. Shield (+4 parry, +2 strike), W.P. Battle Axe (+4 strike, +4 parry, +4 throw, +1D6 damage), W.P. Lance.', NULL, 'Mask of Mer-Folk: grants Swim as a Fish (Superior). Dwarven combat boots: +2D6 on any kick, Telekinetic Leap at will up to 300 feet (100 m), Speed doubled.', 'Minor psychic powers; none are listed and no I.S.P. is printed.', NULL, NULL, 'Enchanted claymore (4D6 total, double damage to demons; three times a day a declared hit forces a save vs magic or the victim suffers a 6th level Paralysis Bolt); magical battle axe (4D6; deals 1D6 to any non-Ogre who touches it); magical plate and chain (A.R. 15, S.D.C. 200, regenerates 10 S.D.C. per hour); the Mask of Mer-Folk, a gilled and finned metal face mask kept for escapes; Dwarven combat boots. Also owns his old pirate ship, land, a mansion and other property.', 'Over a million gold hidden in safes and strongboxes under his home, much of it taken from crews that tried to seize the city; a further two million in the city coffers is his to spend', 'Hard, brutal and calculating, yet fair by his own lights: his word is law and defiance is punished severely, while those who keep his laws are treated generously.', 'About 750 soldiers, guards and enforcers of Troker; the Army of Night, assassins he keeps on retainer', 'The Clemens Crew and Jarvin''s Brigade, who plot to overthrow him; Eshkoven Juijod, a Dragon Wolf with a 50,000 gold bounty on his pelt', 'Tall tattooed ogre, raised as a knight in Timiro and exiled after his mentor died. He conquered Troker''s warring pirate factions and has ruled the Free City as warrior-king for more than 25 years.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.89-94'),
('firyin-kath', 'Firyin Kath', NULL, 'Youngest of the Seven Sons Tribe''s council of chiefs', 'palladium-fantasy', 'Dragonman', '3rd level Mercenary Warrior', 3, 'Anarchist', NULL, NULL, NULL, '{"IQ":11,"ME":7,"MA":9,"PS":18,"PP":14,"PE":22,"PB":3,"Spd":15}', 40, 21, NULL, NULL, NULL, NULL, NULL, NULL, 'Inline stats only; no attacks or bonuses are printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Power-hungry; wants the tribe broken up so he can rule his own, and is prepared to murder brothers to get it.', 'Four other Dragonmen he has recruited', 'The two brothers who most want the tribe kept together', 'One of seven brothers who jointly rule the largest Dragonmen tribe of the Stony Desert; he is plotting assassinations to force a split.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.112-113'),
('deggh-courlik', 'Deggh Courlik', NULL, 'Matriarch of the Ydrogin caravan', 'palladium-fantasy', 'Eandroth (female rogue)', '8th level Mind Mage', 8, 'Scrupulous', NULL, NULL, NULL, '{"IQ":18,"ME":25,"MA":21,"PS":14,"PP":10,"PE":13,"PB":8,"Spd":2}', 55, 100, NULL, NULL, 225, 12, NULL, '{"attacks":5,"strike":2,"parry":2,"dodge":2,"damage":2,"roll":2,"pull":2}', 'Printed bonuses include attribute bonuses. +4% to skill performance, +5 to save vs psionic attack (+11 vs mind control), +6 to save vs magic potions and charms, +5 to save vs possession, 65% to invoke trust or intimidation. Critical strike on 19-20; body flip/throw. A.R. 12 is natural. Her helmet adds a further +2 to save vs all psionic attacks and +4 vs any mind control, illusions included.', NULL, 'Hand to Hand: Basic.', NULL, NULL, 'Mind block, see aura, alter aura, meditation, psychic diagnosis, psychic purification, psychic surgery, increased healing, astral projection, clairvoyance, commune with spirits, telepathy, ectoplasm, impervious to fire, resist thirst, teleport object, deaden pain, lust for life, detect psionics, object read, presence sense, sense magic, sense dimensional anomaly, sixth sense, see the invisible, summon inner strength, float, resist hunger, dispel spirits, empathy, sense evil, induce sleep, exorcism, bio-regeneration (self), and all Super-Psionic powers.', NULL, NULL, 'No weapons. Enchanted leather helmet (+2 to save vs psionic attacks, +4 vs mind control and illusions; hides her psionic ability from Detect Psionics).', 'None', 'Kind and compassionate but ruthless if pushed; once athletic, now too heavy to move much. She would sooner make peace with the Zorigesh than beat them.', 'The Ydrogin caravan', 'The Zorigesh caravan, by blood feud', 'Leader of the 200-strong Ydrogin trading caravan of the Stony Desert, holding back in its feud with the Zorigesh out of love for a Zorigesh warrior she does not know is dead.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.113-114'),
('kimona-lasaatki', 'Kimona Lasaatki', NULL, 'High Warrior of the Kimona Wandercamp', 'palladium-fantasy', 'Quorian', '10th level Soldier', 10, 'Unprincipled', NULL, NULL, NULL, '{"IQ":13,"ME":12,"MA":19,"PS":22,"PP":18,"PE":17,"PB":6,"Spd":19}', 69, 50, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"roll":2,"strike":5,"parry":6,"dodge":6,"pull":6,"damage":10}', 'Printed bonuses include attribute bonuses. +3 to save vs poison, +4 to save vs Horror Factor, +20% to save vs coma/death. Critical strike 18-20, KO/stun 18-20, backward sweep, body throw/flip and disarm. Wears no armor.', NULL, 'Hand to Hand: Expert; W.P. Paired Weapons, W.P. Sword (+4 strike/parry, +2 throw), W.P. Spear (+4 strike/parry, +3 throw), W.P. Shield (+4 parry, +2 strike).', NULL, 'From his enchanted spear only, three times daily in any combination at 6th level: Call Lightning, Ball Lightning, Electrical Field, Plasma Bolt, Electromagnetism, Spark of Life.', 'Commune with Animals, from a ring.', NULL, NULL, 'Enchanted spear (spell-like powers three times daily at 6th level). Two magic rings: one grants Commune with Animals, the other is the Ring of Shaping, an artifact that lets the wearer change form as a Changeling does. No armor.', '231 gold', 'Fierce, passionate and a gifted tactician, devoted to his camp; hot-headed, and his hatred of the Gosai makes him hard to predict. Willing to recruit outsiders who show respect.', 'The young warriors of the Kimona wandercamp', 'The Gosai', 'Greatest warrior of the 59-strong Quorian wandercamp that bears his name, planning a major strike on a Gosai stronghold in the Sandy Desert after a dream-vision.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.115-117'),
('grovoss', 'Grovoss', NULL, 'Dream Shaman of the Bakanshi Wandercamp', 'palladium-fantasy', 'Quorian', '3rd level Mercenary and 1st level Quorian Oneiromancer', 3, 'Principled', NULL, NULL, NULL, '{"IQ":15,"ME":15,"MA":17,"PS":22,"PP":17,"PE":22,"PB":8,"Spd":20}', 32, 40, NULL, NULL, NULL, NULL, NULL, NULL, 'Attributes and pools only; no attacks or bonuses are printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Honest and well-meaning but unproven, and afraid of failing the camp that has put its future in his hands.', 'The Bakanshi wandercamp', NULL, 'Young warrior pushed into the place of the camp''s dead Dream Shaman, Ekensha Ukessa; he intends to lead four chosen warriors south to find the Gate of the Wyrm.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.117'),
('kongo-the-kurayguss', 'Kongo the Kurayguss', NULL, 'Leader of the Claw Law Crew', 'palladium-fantasy', 'Gigante', '6th level Mercenary Warrior and 4th level Assassin', 6, 'Diabolic', NULL, NULL, NULL, '{"IQ":8,"ME":4,"MA":7,"PS":30,"PP":19,"PE":30,"PB":10,"Spd":14}', 70, 100, NULL, NULL, NULL, NULL, NULL, NULL, 'P.S. 30 is supernatural. Mutations give +1 melee attack per round (extra arms) and +2 to initiative (extra eye); no attack total is printed. The +40 S.D.C. from scaly skin is already in the 100.', NULL, NULL, 'Gigante mutations: a second pair of arms, scaly skin, a third eye with 30 ft nightvision, and a large heavy tail.', NULL, NULL, NULL, NULL, 'Giant-sized magical flail with Thunder Hammer (6D6 in all); three potions of healing; a pair of Chaser Crystals; a pair of purple explosive crystals he calls Blasto Rocks; a ring of fire resistance that does not fit his fingers.', NULL, 'Insane as well as evil, and never to be trusted. Kills followers who disagree with him and is fixated on wiping out the Broken Horn Dragonmen.', 'The Claw Law Crew: 72 Orcs, 16 Ogres (among them Sneedle and Braux) and 8 trolls', 'The Broken Horn tribe of Dragonmen', 'Mutant giant who took over a Stony Desert marauder band when his rival Bigoras died, and drives it on in a costly campaign against one Dragonmen tribe.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.118-119'),
('gramazz-the-gray', 'Gramazz the Gray', NULL, 'Chief of the Bloodstorm Crew', 'palladium-fantasy', 'Orc', '7th level Thief and 3rd level Ranger', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":13,"ME":13,"MA":19,"PS":27,"PP":18,"PE":18,"PB":10,"Spd":21}', 65, 35, NULL, NULL, NULL, NULL, NULL, '{"attacks":5,"strike":4,"parry":5,"dodge":5,"damage":12,"roll":5,"pull":5}', 'Printed bonuses include attribute bonuses. He uses his Dragon Claws as paired weapons, which the block says effectively doubles his attacks per melee. +2 to save vs magic, +6% vs coma/death. Wears no armor.', NULL, 'Hand to Hand: Expert; W.P. Paired Weapons, W.P. Sword (+3 strike/parry, +1 throw), W.P. Knife (+3 strike/parry/throw), W.P. Archery (ROF 4, +80 ft range, +2 strike/parry), W.P. Spear (+3 strike/parry, +2 throw). Horsemanship: Exotic with +10% on a Silonar, as all of his crew.', NULL, 'Through his Dragon Helm (80 P.P.E., regains 4D6 every three hours), cast at his own level: Blinding Flash, See Aura, See the Invisible, Sense Evil, Sense Magic, Thunderclap, Climb, Turn Dead, Armor of Ithan, Energy Bolt, Sense Traps, Carpet of Adhesion, Energy Field, Magic Net, Multiple Image, Shadow Meld, Tongues.', NULL, NULL, NULL, 'A pair of indestructible Dragon Claws (6D6 per hit); a Sorcerer''s Dragon Helm (80 P.P.E.). No armor. Rides a Silonar.', 'About 600 gold', 'Charismatic, sharp and even-handed, with a personal code his crew has taken up; gives most of his loot away as bonuses and lives for the adventure.', 'The Bloodstorm Crew, including Nee''arl, Margolii the Wonderous, Krifosto the Kind and Brutana the She-Devil', NULL, 'Third-generation leader of a fifty-year-old band of mounted desert robbers known for sparing women and children and leaving victims enough to survive on.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.119-120'),
('rogayashi', 'Rogayashi', NULL, 'Leader of the Damnation Crew and captain of the Orcish Delight', 'palladium-fantasy', 'Ogre', '7th level Thief and 1st level Pirate', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":14,"ME":12,"MA":14,"PS":25,"PP":25,"PE":25,"PB":14,"Spd":11}', 60, 45, NULL, NULL, NULL, NULL, NULL, NULL, 'Inline stats only; no attacks or bonuses are printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Commands the Orcish Delight, an ancient Dwarven Juggernaut land-ship; likes to rope its ballista arrows to harpoon victims. Keeps the crew''s cash aboard.', 'A small fortune in cash, kept on the Orcish Delight', 'Crafty, power-hungry and growing more reckless as his fame spreads; lets any crewman leave with his share.', 'The Damnation Crew, over a hundred marauders', 'Eandroth caravans (25,000 gold on his head), Gromek garrisons, bounty hunters, Western Empire agents after his vehicle', 'Son of Old Kingdom slaves who murdered his way to the top of a bandit gang, was its only survivor, and now terrorises the Stony Desert from a recovered Dwarven war machine.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.121'),
('grillek-ibesstissen', 'Grillek Ibesstissen', NULL, 'Commander of Raag Akettikik', 'palladium-fantasy', 'Gromek', '8th level Knight', 8, 'Miscreant', NULL, NULL, NULL, '{"IQ":12,"ME":10,"MA":11,"PS":22,"PP":17,"PE":16,"PB":7,"Spd":6}', 57, 45, NULL, NULL, NULL, NULL, NULL, NULL, 'Spd 6 is running; flying speed is 33. No attacks or bonuses are printed.', NULL, NULL, 'Flies (Spd 33).', NULL, NULL, NULL, NULL, NULL, NULL, 'Career soldier who loves combat and resents a desert posting far from the war with the giants; orders patrols to return with an enemy''s head or not return.', 'The 28 Gromek soldiers of his camp', 'Giants; lately curious about the Damnation Crew', 'Decorated veteran of the giant wars commanding a 29-soldier walled war camp in the Stony Desert, whose patrols have destroyed small caravans and adventuring parties.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.124-125'),
('agek-ta-k-t-kusssa', 'Agek''ta''k T''kusssa', NULL, 'Commander of Raag Borguni', 'palladium-fantasy', 'Gromek', '11th level Soldier', 11, 'Aberrant', NULL, NULL, NULL, '{"IQ":13,"ME":15,"MA":11,"PS":24,"PP":15,"PE":17,"PB":8,"Spd":8}', 54, 53, NULL, NULL, NULL, NULL, NULL, NULL, 'Spd 8 is running; flying speed is 31. No attacks or bonuses are printed.', NULL, NULL, 'Flies (Spd 31).', 'His claymore throws a lightning bolt three times a day.', NULL, NULL, NULL, 'Giant-sized claymore that fires lightning bolts three times a day (each discharge does 1D6 to the wielder unless resistant to electricity); a sack of 3,500 gold in Old Kingdom coins; a collection of humanoid skulls.', '3,500 gold in Old Kingdom coins', 'Level-headed strategist who believes in a Gromek empire built with outside help; offers wanderers a place in it or a warning to leave, and his camp prefers ruling lesser peoples to killing them.', '63 Gromek plus Ogre, Orc and Melech squads and a Changeling assassin, Sphinx wizard, Loogaroo, Manticore and Thin One agents', 'Looked down on by other Gromek commanders', 'Military genius sidelined to the Stony Desert with a command of misfits, which he has drilled into the best war band in the region and is quietly growing into an army.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.125'),
('egreiga-koge', 'Egreiga Koge', NULL, 'Commander of Raag Zetronenki', 'palladium-fantasy', 'Gromek', '8th level Knight', 8, 'Aberrant (with diabolic leanings)', NULL, NULL, NULL, '{"IQ":9,"ME":12,"MA":11,"PS":24,"PP":17,"PE":24,"PB":11,"Spd":11}', 69, 60, NULL, NULL, NULL, NULL, NULL, NULL, 'Spd 11 is running; flying speed is 20, reduced by an old wing wound. No attacks or bonuses are printed.', NULL, NULL, 'Flies (Spd 20), with some difficulty since a wing injury.', 'From an indestructible sandstone ring, up to three times daily in any combination at 6th level: Dust Storm, Dirt to Sand, Quicksand, Sandstorm.', NULL, NULL, NULL, 'Giant-sized non-magical flamberge (4D6); ring of sandstone; 100 ft Cherubot rope; Gem of Direction; a vial of Miracle Cream.', 'Over 40,000 gold in mixed coin', 'Arrogant egomaniac who holds every other race in contempt and treats even his own troops harshly; tolerated for his fame as a giant-killer.', '280 Gromek troops', 'Giants; all non-Gromek', 'Commander of the largest and oldest Stony Desert war camp, a village-sized forward post holding 280 soldiers and 160 slaves, its walls hung with the wings of soldiers he judged disloyal.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.126'),
('ab-al', 'Ab''al', NULL, 'Leader of Ab''al''s Caravan', 'palladium-fantasy', 'Eandroth (female rogue)', '9th level Mind Mage', 9, 'Unprincipled', NULL, NULL, NULL, '{"IQ":21,"ME":26,"MA":26,"PS":14,"PP":13,"PE":13,"PB":10,"Spd":3}', 68, 75, NULL, NULL, NULL, NULL, NULL, NULL, 'Inline stats only; no attacks, bonuses or I.S.P. are printed.', NULL, NULL, NULL, NULL, 'Uses broad empathic transmissions to keep a herd of over 150 Silonar docile; no power list is printed.', NULL, NULL, 'Rides in the caravan''s only wagon.', NULL, 'Too heavy to move unaided; holds a herd of vicious animals calm with her mind while her herders work it.', 'Her 30 Eandroth herders, all 3rd to 5th level Rangers; the Bloodstorm Crew, who buy her Silonar', NULL, 'Sole female and leader of a 31-member Eandroth herding caravan that catches, breaks and sells Silonar on a yearly circuit of the Wastelands.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.133'),
('mubulu', 'Mubulu', NULL, 'Elder of the Gthnenen Tribe', 'palladium-fantasy', 'Gosai', '4th level Wizard', 4, 'Unprincipled', NULL, NULL, NULL, '{"IQ":15,"ME":14,"MA":13,"PS":17,"PP":17,"PE":10,"PB":10,"Spd":14}', 30, 30, NULL, 52, NULL, NULL, NULL, '{"attacks":5,"strike":2,"parry":3,"dodge":3,"damage":2,"roll":2,"pull":2}', 'No W.P.s; fights with his claws if forced to (no claw damage is printed here). Wears no armor. His staff raises his spell strength by one level.', NULL, 'No W.P.s.', 'Gosai claws.', 'All Common Knowledge spells plus Sense Magic, Decipher Magic, Chameleon, Befuddle, Telekinesis, Ley Line Transmission, See Aura, Fear, Paralysis: Lesser, Repel Animals. His staff casts a thorn-vine Magic Net three times daily at 6th level (2D4 to a captive per action or movement spent struggling).', NULL, NULL, NULL, 'Indestructible magic staff: a 100 P.P.E. battery regaining 1D6 per hour, +1 level of spell strength, strikes as an iron staff, casts a thorny Magic Net three times daily. A few other enchanted items and a satchel of personal effects.', '100 gold', 'Wise and well-travelled; has decided the desert no longer wants his people and may accept help from well-mannered outsiders.', 'The Gthnenen tribe (25 adults, 12 children)', NULL, 'Wizard elder leading a dwindling Gosai tribe out of the Sandy Desert toward Troker, where he means them to hire out as fighters. The block''s text also spells his name Mbulu.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.135-136'),
('churluo', 'Churluo', NULL, 'Elder of the Duryops Tribe and Keeper of the Forest', 'palladium-fantasy', 'Gosai', '9th level Ranger', 9, 'Unprincipled', NULL, NULL, NULL, '{"IQ":9,"ME":14,"MA":10,"PS":13,"PP":19,"PE":15,"PB":11,"Spd":21}', 40, 30, NULL, NULL, NULL, NULL, NULL, '{"attacks":5,"initiative":1,"strike":4,"roll":4,"pull":4,"parry":5,"dodge":5}', 'Wears no armor.', NULL, 'Hand to Hand: Expert; W.P. Archery and W.P. Sword.', NULL, NULL, NULL, NULL, NULL, 'Arhalej, Slayer of Fiends: a magic longbow that shoots as a Great Bow (1,500 ft, 5D6, double damage to demons and deevils). A pouch of enchanted seeds and nuts from at least 25 extinct plant species, which sprout at once in fertile soil.', 'Nothing noteworthy', 'Cautious and sober, worn down by an inherited duty; would hand the seeds to honorable adventurers who swore a blood pact over them.', 'The Duryops tribe (77 members, 20 of them Rangers)', NULL, 'Ranger elder whose family has guarded the last seeds of the vanished Baalgor rainforest since the Elf-Dwarf War, with nowhere in the desert to plant them.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.136-137'),
('xevesstssn', 'Xevesstssn', NULL, 'High Commander of the Sandy Desert', 'palladium-fantasy', 'Gromek', '9th level Knight', 9, 'Aberrant', NULL, NULL, NULL, '{"IQ":13,"ME":14,"MA":16,"PS":20,"PP":20,"PE":20,"PB":5,"Spd":10}', 65, 40, NULL, NULL, NULL, NULL, NULL, '{"attacks":7,"initiative":2,"strike":5,"parry":6,"dodge":6,"roll":5,"pull":6,"damage":7}', 'Printed bonuses include attribute bonuses. Spd 10 is running; flying speed is 35. +5 to disarm, +3 to save vs magic and poison, +10% vs coma/death. Backward sweep, tripping/leg hook, all jump kicks, leap attack (critical strike), critical strike 18-20. Owns plate and mail (A.R. 17, S.D.C. 160) but wears it only for show.', NULL, 'Hand to Hand: Martial Arts; W.P. Paired Weapons, W.P. Lance (per the Knight O.C.C.), W.P. Sword (+4 strike, +3 parry, +2 throw), W.P. Shield (+4 parry, +2 strike), W.P. Pole Arms (+4 strike/parry/damage, +2 throw), W.P. Battle Axe (+4 strike/parry/dodge, +1D6 damage).', 'Flies (Spd 35).', NULL, NULL, NULL, NULL, 'Lance for flying charges; a pair of magic battle axes (3D6) that return when thrown; made-to-fit plate and mail (A.R. 17, S.D.C. 160), seldom worn; a Screech Bottle, 6 Magic Bandages, 2 Magical Restraints, 2 potions of Might of the Palladium.', '1,500 gold in Old Kingdom currency, 1,000 in Western currency, and four diamonds worth 2,000, 1,200, 900 and 800', 'Rigid, cold and bloodthirsty yet scrupulously honorable toward Gromek and giants alone; smaller peoples are beneath any such duty. Nicknamed Wingcutter for how he punishes deserters.', 'Raag Raxux: 154 personnel including three hired Eandroth Warlocks, with Drayback and Silonar herds', 'Giants; Eandroth and Gosai of the Sandy Desert', 'Famed Gromek warrior commanding the tent-built primary war camp of the Sandy Desert, whose bored troops he keeps sharp by setting them on travellers.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.136-139'),
('commander-orgizeg', 'Commander Orgizeg', NULL, 'Commander of Raag Gesiiq', 'palladium-fantasy', 'Gromek', '7th level Soldier', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":9,"ME":15,"MA":4,"PS":21,"PP":18,"PE":21,"PB":6,"Spd":6}', 49, 30, NULL, NULL, NULL, NULL, NULL, NULL, 'Spd 6 is running; flying speed is 29. No attacks or bonuses are printed.', NULL, NULL, 'Flies (Spd 29).', NULL, NULL, NULL, NULL, NULL, NULL, 'Arrogant megalomaniac sure of his own perfection, who will blame any failure on his subordinates.', 'The 50 troops of Raag Gesiiq, with 50 Draybacks and 10 Silonar', NULL, 'Commander of a trade-route war camp whose standing order to shake down every traveller has left his soldiers overconfident and unready for real opposition.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.139'),
('ferigut', 'Ferigut', NULL, 'Sole survivor of Raag Cojoda', 'palladium-fantasy', 'Gromek', '2nd level Soldier', 2, 'Anarchist', NULL, NULL, NULL, '{"IQ":7,"ME":7,"MA":7,"PS":19,"PP":15,"PE":17,"PB":7,"Spd":7}', 45, 45, NULL, NULL, NULL, NULL, NULL, NULL, 'Spd 7 is running; flying speed is 36. No attacks or bonuses are printed.', NULL, NULL, 'Flies (Spd 36).', NULL, NULL, NULL, NULL, NULL, NULL, 'A thorough coward and shirker who will latch onto any adventuring party, complain, covet and possibly betray it, but is kept in line by threats.', NULL, 'The giants of Gurthasi Tor; his own people, who would clip his wings for deserting', 'Low-ranking soldier who fled when giants slaughtered his whole camp and now hides within sight of it, unsure where to go.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.139'),
('nekaradon', 'Nekaradon', NULL, 'Leader of the Adraodan tribe', 'palladium-fantasy', 'Adraodan Minotaur', '3rd level Crusader of Light', 3, 'Principled', '92', NULL, NULL, '{"IQ":10,"ME":15,"MA":21,"PS":21,"PP":24,"PE":20,"PB":11,"Spd":20}', 41, 24, NULL, NULL, NULL, NULL, NULL, NULL, 'Inline stats only; racial figures (natural A.R., Horror Factor, damage) are those of the Adraodan Minotaur R.C.C. on p.142-143 and are not repeated for her.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Noble and selfless; plans to go north alone once her people are safely out of the Wastelands so that they find their own way.', 'The Adraodan Minotaurs', 'The Kkairojan Minotaurs', 'Young by Minotaur reckoning and held to be the best warrior her tribe of good-aligned Minotaurs has produced.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.143'),
('gruegas-wierdling', 'Gruegas Wierdling', NULL, 'Leader of the Kkairojan tribe', 'palladium-fantasy', 'Kkairojan Minotaur', '8th level Witch/Disciple of the Old Ones', 8, 'Diabolic', NULL, NULL, NULL, '{"IQ":12,"ME":14,"MA":13,"PS":25,"PP":18,"PE":25,"PB":15,"Spd":15}', 57, 100, NULL, NULL, NULL, NULL, NULL, NULL, 'Inline stats only; racial figures are those of the Kkairojan Minotaur R.C.C. on p.144 and her class is detailed in Old Ones, 2nd Edition. Nothing further is printed for her here.', NULL, NULL, NULL, 'Witchcraft by pact with the Old Ones; no spell list is printed.', NULL, NULL, NULL, NULL, NULL, 'Fanatical servant of the Old Ones, eager to loose her tribe on the surface world.', 'Five 4th level witches of the Old Ones; the 1300 Kkairojan', 'The Adraodan Minotaurs', 'Witch who heads the man-eating, Old Ones-worshipping Minotaur tribe as it prepares to leave the Wastelands and scatter into small cult bands.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.144-145'),
('unom', 'Unom', NULL, 'Leader of the Me''khed Caravan', 'palladium-fantasy', 'Eandroth (Rogue male)', '6th level Merchant, 3rd level Ranger', 6, 'Anarchist', NULL, NULL, NULL, '{"IQ":11,"ME":18,"MA":7,"PS":15,"PP":18,"PE":18,"PB":8,"Spd":14}', 72, 60, NULL, NULL, 92, 15, NULL, '{"attacks":6,"initiative":1,"strike":3,"parry":4,"dodge":4,"roll":4,"pull":4}', '+2 to save vs magic and poison, +6% to save vs coma/death. Critical strike 19-20. A.R. 15 is his magical scale mail (100 S.D.C.).', NULL, 'Hand to Hand: Expert and Boxing; W.P. Knife (+1 strike, +2 parry/throw), W.P. Archery (ROF 5, +120 ft range, +4 strike/parry), W.P. Sword (+2 strike, +1 parry), W.P. Spear (+2 strike/parry, +1 throw).', NULL, NULL, 'Major psionic: Ectoplasm, Mind Block, Nightvision, Summon Inner Strength, Telekinetic Punch, Telekinetic Leap, Teleport Object.', NULL, NULL, 'Eandroth double-bladed knife (2D4); magical scale mail (A.R. 15, S.D.C. 100), sparkling green, weightless and fire resistant; Caalal, an Elven magic crossbow from the Elf-Dwarf War whose missiles count as magical and which three times daily turns one missile into a 7D6 fireball, lightning bolt or wind rush (worth 500,000 gold or more).', 'Four Old Kingdom Dragon Coins (5,000 gold each) and 1,334 gold in Western currency', 'Holds his psionics back for emergencies and expects to hand the caravan over once a female rogue turns up.', 'The Me''khed Eandroth', NULL, 'Took charge of the Me''khed a few months ago after a scorpion sting killed the female rogue who led it. The caravan trades with giants and Gromek alike, which is starting to anger both.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.151'),
('skddn-ros-kdda', 'Skddn Ros Kdda', NULL, 'Cyclops advisor at Loghur Stronghold', 'palladium-fantasy', 'Cyclops', '7th level Soldier', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":17,"ME":6,"MA":12,"PS":29,"PP":19,"PE":19,"PB":6,"Spd":8}', 54, 70, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Power-hungry and no patriot: he has weighed deposing the commander, and might then turn the garrison to banditry or sell it to the Gromek.', NULL, NULL, 'The lone Cyclops among Loghur''s thirty giants, appalled by how far the idle garrison''s discipline has slipped.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.153'),
('commander-stone-hammer', 'Stone Hammer', NULL, 'Commander of Loghur Stronghold', 'palladium-fantasy', 'Jotan', '7th level Ranger', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":12,"ME":17,"MA":10,"PS":40,"PP":23,"PE":24,"PB":7,"Spd":12}', 59, 90, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, 'W.P. Sword, W.P. Chain.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Even-tempered and popular with his troops; he has eased discipline on purpose and sends out scouting, hunting and recruiting parties to give them something to do.', 'The giants of Loghur Stronghold', 'Gromek', 'Unusually bright Jotan who runs the bored Loghur garrison and suspects the Gromek fly-bys are meant to wear his men down.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.153'),
('goliko-edrex', 'Goliko Edrex', NULL, 'Leader of the Fortress of Three (Yrymin Stronghold)', 'palladium-fantasy', 'Nimro', '8th level Fire Warlock', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":10,"ME":17,"MA":14,"PS":23,"PP":20,"PE":28,"PB":15,"Spd":11}', 60, 70, NULL, 172, NULL, 14, NULL, '{"attacks":5,"initiative":1,"strike":5,"parry":6,"dodge":6,"roll":2,"pull":2,"damage":10}', 'Five attacks by hand to hand or two by spell magic. +7 to save vs magic and poison, +26% to save vs coma/death. A.R. 14 is natural, from his magical Ironhide Ring, while it is worn. A second ring raises his spell level by two.', NULL, 'Hand to Hand: Basic; W.P. Blunt (+3 strike/parry/throw), W.P. Chain (+3 strike, +2 parry).', NULL, 'Blinding Flash, Fiery Touch, Stench of Hades, Cloud of Ash, Darkness, Tongue of Flame, Circle of Flame, Fireball, Wall of Flame, Flame Friend, Fuel Flame, Mini-Fireballs, Eat Fire, Screaming Wall of Flame, Wall of Ice, Eternal Flame, Flame of Life, Fire Whip, Fire Sponge, River of Lava, Ten Foot Wheel of Fire, Burst Into Flame, Drought, Plasma Bolt.', NULL, NULL, NULL, 'Giant-sized ball and chain (4D6). No armor; Ironhide Ring (natural A.R. 14, resizes to any wearer from gnome to giant); an ornate ring that boosts his spell level by two, said to be one of a set of four elemental rings. Carries papers from the giant High Command at Nimro naming the three as soldiers of the Kingdom of Giants.', '25,000 gold in rubies, diamonds and emeralds', 'Aggressive and ambitious, yet a patriot who puts the Nimro Kingdom ahead of himself. Covets a flaming magic ball and chain and dreams of collecting the other three rings.', 'Lldirrn, Quake', 'Gromek', 'Leads the three giant adventurers who rebuilt the abandoned Yrymin Stronghold, by default since his partners do not want the job. Treats the trio as a special strike force.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.154-155'),
('lldirrn', 'Lldirrn', NULL, 'Sniper of the Fortress of Three (Yrymin Stronghold)', 'palladium-fantasy', 'Cyclops', '8th level Cyclops Long Bowman', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":19,"ME":9,"MA":15,"PS":29,"PP":17,"PE":21,"PB":10,"Spd":8}', 53, 80, NULL, NULL, NULL, 14, NULL, '{"attacks":5,"strike":4,"parry":6,"dodge":6,"roll":2,"pull":2,"damage":16}', 'Five attacks hand to hand, eight with a long bow. +3 to save vs magic and poison, +12% to save vs coma/death, +4% to all skills. A.R. 14 is his giant-sized Leather of Iron (212 S.D.C.). His bow adds the user''s P.S. damage bonus, up to +10, and 100 ft of range per P.S. point above 20.', NULL, 'Hand to Hand: Expert; W.P. Archery (+5 strike/parry), W.P. Targeting (+6 strike), W.P. Sword (+3 strike/parry, +2 throw), W.P. Blunt (+3 strike/parry/throw).', 'Makes Cyclops Lightning Shafts, a craft learned from his father, at a forge he built in the stronghold.', NULL, NULL, NULL, NULL, 'Magical giant-sized long bow from the Isle of the Cyclops, strung with indestructible metal (P.S. 18 needed to draw); V-shaped double quiver of 48 arrows, with 2D4x10 more cached at the stronghold; giant-sized Leather of Iron (A.R. 14, S.D.C. 212); belt satchel with a permanent Dimensional Pocket holding 48 ordinary and 48 Lightning arrows, a spare ordinary long bow, 2D4 darts, water and hard candy. Stock on hand: two dozen lightning javelins and 96 lightning arrows, all maximum damage.', '20,000 gold, kept in the satchel', 'Unhurried and detached about killing.', 'Goliko Edrex, Quake', 'Gromek', 'Marksman of the Yrymin trio, deadly at any bow range despite the single eye, and the group''s source of lightning weapons.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.154-155'),
('quake-algor', 'Quake', NULL, 'Warrior of the Fortress of Three (Yrymin Stronghold)', 'palladium-fantasy', 'Algor', '8th level Mercenary Warrior', 8, 'Miscreant', NULL, NULL, NULL, '{"IQ":7,"ME":13,"MA":6,"PS":35,"PP":25,"PE":26,"PB":6,"Spd":24}', 66, 95, NULL, NULL, NULL, 15, NULL, '{"attacks":8,"initiative":1,"strike":7,"parry":12,"dodge":12,"roll":6,"pull":5,"damage":24}', 'P.S. 35 is printed as supernatural. +4 to disarm, +6 to save vs magic and poison, +3 to save vs Horror Factor. Pin/incapacitate 18-20, KO/stun 17-20. A.R. 15 is his giant-sized double mail (55 S.D.C.). Insanity: semi-functional mindless aggression, and a hatred of all clergy.', NULL, 'Hand to Hand: Expert, Boxing, Wrestling; W.P. Sword (+3 strike/parry, +2 throw), W.P. Shield (+2 strike, +3 parry), W.P. Chain (+3 strike, +2 parry), W.P. Battle Axe (+3 strike, +2 parry/throw), W.P. Pole Arm (+4 damage, +3 strike/parry, +2 throw).', NULL, NULL, NULL, NULL, NULL, 'Non-magical giant-sized battle axe (5D6), flamberge (4D6), ball and chain (4D6) and Berdiche (4D6+4); giant-sized double mail, magically weightless and noiseless (A.R. 15, S.D.C. 55), which he treats as disposable. No magic items.', 'None; he spends what he earns and leans on his partners', 'Battle-crazed: takes needless risks, will not withdraw, and goes for the strongest enemy in reach. Only his two partners can talk him down.', 'Goliko Edrex, Lldirrn', 'Gromek; clergy of every kind', 'The reckless muscle of the Yrymin trio, alive only because the other two cover for him.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.154-156'),
('ckurlka', 'Ckurlka', NULL, 'Leader of the Burrow of Ozoerod', 'palladium-fantasy', 'Baalizad', 'The equivalent of a 6th level Mercenary Fighter', 6, 'Anarchist', NULL, NULL, NULL, '{"IQ":21,"ME":15,"MA":15,"PS":24,"PP":11,"PE":30,"PB":6,"Spd":5}', 55, 95, NULL, NULL, NULL, 14, NULL, '{"attacks":5,"strike":4,"parry":5,"dodge":5,"damage":9,"roll":3,"pull":2}', 'Spd 5 applies running or digging. +8 to save vs magic and poison, +30% to save vs coma/death. Pin/incapacitate 18-20, critical strike 18-20. A.R. 14 is natural.', NULL, 'Hand to Hand: Basic and Wrestling.', 'Lobster-like claws, and a superheated plasma breath usable once a melee and three times a day; whatever it hits keeps burning for 1D4 melees until put out.', NULL, NULL, NULL, NULL, 'No weapons, armor, magic items, money or gear.', 'None', 'The burrow''s fiercest fighter and its sharpest planner, credited with many dead surface-goers.', 'The Ozoerod Baalizad', 'Giants, Gromek and surface folk generally', 'Outsized Baalizad who leads the embittered Ozoerod tribe. Without this leader the burrow would drift for some weeks before a successor emerged.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.159'),
('keisel-the-undying', 'Keisel the Undying', NULL, 'High priest of the Loijurkan death cult', 'palladium-fantasy', 'Minotaur', '10th level Priest of Darkness', 10, 'Diabolic', NULL, NULL, NULL, '{"IQ":13,"ME":18,"MA":18,"PS":18,"PP":10,"PE":30,"PB":5,"Spd":7}', 80, 64, NULL, NULL, NULL, NULL, NULL, NULL, 'No combat line is printed. Each minute exposed to sunlight, running water or lush vegetation he must save vs nonlethal poison (14 or higher) or suffer acute nausea: attacks per melee halved, all combat bonuses lost, skills at -20%.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Obsessed with death in every form and physically sickened by signs of life.', 'The Loijurkan priests of Utu', NULL, 'Heads the cabal of Utu-worshipping priests that has ruled the roughly 280 Loijurkan Minotaurs and driven them to murder outsiders as tribute.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.161'),
('luurna', 'Luur''na', NULL, 'One of the Chosen Eight of the Etrinan Tribe', 'palladium-fantasy', 'Minotaur', '2nd level Priestess of Light (Isis)', 2, 'Scrupulous', '23', NULL, NULL, '{"IQ":12,"ME":11,"MA":9,"PS":22,"PP":15,"PE":18,"PB":19,"Spd":10}', 26, 50, NULL, NULL, NULL, NULL, NULL, NULL, 'No combat line is printed. Her rune staff''s healing/cleric abilities are deferred to pages 250-252 of the Palladium Fantasy RPG, 2nd Edition.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Saraph, a greater rune weapon of the Lightbringer / Holy Rune Weapon kind: a nine foot ornate silver staff with gold runes, scrupulous, 4D6 damage (double to supernatural evil), all basic rune weapon features plus healing/cleric abilities.', NULL, 'Means to wander and let fate decide; the one member of her band whose good alignment is expected to hold.', 'Zii''clymnt and seven other Etrinan youths', NULL, 'Young Etrinan priestess of Isis who, with her boyfriend, has gathered seven other youths to leave the dying tribe and see the world.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.161-162'),
('ziiclymnt', 'Zii''clymnt', NULL, 'One of the Chosen Eight of the Etrinan Tribe', 'palladium-fantasy', 'Minotaur', '2nd level Ranger', 2, 'Anarchist', '19', NULL, NULL, '{"IQ":9,"ME":10,"MA":8,"PS":28,"PP":19,"PE":25,"PB":14,"Spd":24}', 22, 72, NULL, NULL, NULL, NULL, NULL, NULL, 'No combat line is printed. The sword''s 90 P.P.E. is its own, not his. Greater rune weapon details are deferred to page 250 of the Palladium Fantasy RPG, 2nd Edition.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Lightning Striker, a greater rune weapon: six foot black long sword with silver runes, anarchist, 6D6 damage, all basic rune weapon features, 90 P.P.E., casting Call Lightning, Electrical Field, Wind Rush, Levitate, Invisibility (itself and wielder) and Breath of Life.', NULL, 'Already drifting toward miscreant.', 'Luur''na and seven other Etrinan youths', NULL, 'Luur''na''s boyfriend and partner in leading a band of young Etrinan Minotaurs out into the world.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.162'),
('grounna', 'Groun''na', NULL, 'One of the Chosen Eight of the Etrinan Tribe', 'palladium-fantasy', 'Minotaur', '6th level Mercenary Warrior', 6, 'Miscreant', '59', NULL, NULL, '{"IQ":10,"ME":12,"MA":13,"PS":25,"PP":16,"PE":21,"PB":12,"Spd":12}', 56, 67, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"strike":3,"roll":3,"pull":3,"parry":4,"dodge":4,"damage":14}', '+4 to disarm. KO/stun 17-20. Hates Elves. Egebba itself is +3 to strike when thrown.', NULL, 'Body flip/throw; W.P. Sword (+3 strike/parry, +1 throw), W.P. Shield (+3 parry, +1 strike), W.P. Targeting (+4 strike), W.P. Battle Axe (+3 strike/parry/dodge, +1D6 damage).', NULL, NULL, NULL, NULL, NULL, 'Egebba, a runic chakram (bladed flying ring), 5D6 per hit, all basic runic powers; it relishes combat and goads its user but never tries to dominate him. Returns when thrown; range as far as the user can see, up to 2000 ft, +3 to strike. Four special strikes a day: power strike (as a 6th level Wind Rush), fire strike (1D6x10 fire ball), mirrored triple-strike (three copies at 5D6 each, +1 to strike if split across targets), guided strike (misses only on a natural 1, dodged only on a natural 20, follows a target seen when thrown).', NULL, 'Impulsive bully who wants to find weaker peoples to subjugate, and who hates the tribemates that rebuked him.', 'Two dim 3rd level Minotaur thieves, both miscreant, carrying lesser rune weapons', 'Mergerij; the other Etrinan youths; Elves', 'Among the oldest of the eight Etrinan rune-bearers. Likely to end up conquering a village with a gang of villains or serving as a brutal officer for the giants.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.162'),
('mergerij', 'Mergerij', NULL, 'One of the Chosen Eight of the Etrinan Tribe', 'palladium-fantasy', 'Minotaur', 'Effectively a 4th level Palladin, minus the lance W.P.', 4, 'Principled', '20', NULL, NULL, '{"IQ":10,"ME":21,"MA":9,"PS":23,"PP":20,"PE":20,"PB":9,"Spd":18}', 42, 69, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"pull":4,"roll":4,"strike":7,"parry":10,"dodge":10,"damage":10}', '+2 to disarm, +3 to save vs magic and poison, +10% to save vs coma/death, +6 to save vs Horror Factor. Critical strike 18-20. The dagger''s 110 I.S.P. is its own, not his. Cutter is +1 to parry and makes its wielder impervious to heat and fire. Sticker carries the Dislike curse (page 263 of the 2nd Edition rule book).', NULL, 'Hand to Hand: Martial Arts and Palladin Special Training, all jump kicks; W.P. Sword (+3 strike, +2 parry, +1 throw), W.P. Shield (+3 parry, +1 strike), W.P. Blunt (+3 strike/parry), W.P. Spear (+3 strike/parry, +2 throw). No W.P. Lance.', NULL, NULL, NULL, NULL, NULL, 'A matched pair of rune weapons with crimson blades and silver and pearl handles, both with all basic rune weapon properties. Cutter, short sword: +1 parry, 6D6, spits 6D6 fire balls ten times a day, wielder impervious to heat and fire. Sticker, dagger: all physical psionic powers plus Electrokinesis and Catatonic Strike, 110 I.S.P., cursed with Dislike.', NULL, 'Self-righteous and given to lecturing; sees everything as plainly good or plainly evil.', NULL, 'Groun''na', 'The most respected of the eight Etrinan rune-bearers, who argues the tribe''s arsenal should be used to better the world and atone for Minotaur crimes.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.162-163'),
('zeelik-stonemace', 'Zeelik Stonemace', NULL, NULL, 'palladium-fantasy', 'Minotaur', 'A first level Palladin, minus the lance W.P.', 1, 'Principled', '16', NULL, NULL, '{"IQ":10,"ME":19,"MA":12,"PS":21,"PP":21,"PE":20,"PB":12,"Spd":17}', 25, 59, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"pull":3,"roll":3,"strike":3,"parry":4,"dodge":4,"damage":6}', '+3 to save vs magic and poison, +10% to save vs coma/death, +6 to save vs Horror Factor. P.S., P.P. and P.B. each rise 1D4 and S.D.C. rises 5D6 by 4th level. The mace''s 80 P.P.E. is its own, not his.', NULL, 'Hand to Hand: Martial Arts and Palladin Special Training; W.P. Shield (+1 parry), W.P. Sword (+1 strike), W.P. Blunt (+1 strike/parry), W.P. Spear (+1 strike/parry). No W.P. Lance.', NULL, NULL, NULL, NULL, NULL, 'Anzuroq, a stone rune mace inherited from his father, older than the Elf-Dwarf War and perhaps not Dwarven; 1D4x10 per hit and all common rune powers. Its personality is a patriot''s, without hatred of Elves. 80 P.P.E. battery (regains 10 an hour) casting at 6th level Hopping Stones, Animate Plants, Quicksand, Rust, Wall of Thorns and Travel Through Earth. Three times a day a hit can petrify permanently (save vs magic 14+, as the 7th level Earth Warlock spell Petrification); three taps of the mace undo it. Curse: all but principled users run a 5% chance of being petrified whenever it is used for other than honorable ends, and once every 10 years.', NULL, 'Shy, gentle and trustworthy, but observant and quick in a fight and without mercy for a real enemy.', NULL, NULL, 'Not one of the eight, and underrated by the Etrinan. A former pupil of Mergerij who found him too self-absorbed and is heading to the surface alone; the book marks him out as a future hero.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.163-164'),
('xexin-vidaav', 'Xexin Vidaav', NULL, 'Champion of the Serelan Tribe', 'palladium-fantasy', 'Minotaur', '9th level Palladin', 9, 'Scrupulous', '232', NULL, NULL, '{"IQ":9,"ME":13,"MA":19,"PS":26,"PP":20,"PE":26,"PB":10,"Spd":18}', 67, 80, NULL, NULL, NULL, 17, NULL, '{"attacks":8,"initiative":2,"strike":5,"parry":8,"dodge":8,"damage":11,"pull":3,"roll":4}', '+2 to disarm, +6 to save vs Horror Factor, and a further +4 to save vs any mind control that would make him act against his alignment. Critical strike 18-20, KO on a natural 20, leap attack is a critical strike. A.R. 17 is his weightless, noiseless plate and mail (160 S.D.C.); his spare Cloak of Iron is A.R. 15, S.D.C. 300. The book also spells the name Xixin and Xexin Vidraav.', NULL, 'Hand to Hand: Martial Arts, Boxing and Special Palladin Training, tripping/leg hook, all jump attacks; W.P. Paired Weapons, W.P. Lance, W.P. Sword (+4 strike, +3 parry, +2 throw), W.P. Shield (+4 parry, +2 strike), W.P. Spear (+4 strike/parry, +2 throw), W.P. Chain (+3 strike, +2 parry), W.P. Forked/Trident (+4 strike/entangle, +3 parry, 1 throw).', NULL, NULL, NULL, NULL, NULL, 'The Millennium Spear, cut from a holy tree of the Great Northern Wilderness: 5D6 plus his damage modifiers, usable properly only by the good (selfish -5 strike/parry/dodge and half damage; evil -10 and quarter damage). Double Thunder Kata: its two bladed ends work as paired weapons, constantly. Special katas, three uses a day in any mix: Whirlwind (parry nearly any incoming attack, missiles included, though not magical or energy blasts), Lightning (all the round''s attacks in one blow for 1D6x10+88, no other damage bonus, then no dodge and unmodified parries that round), Purity (next hit is a critical for double damage, triple on a natural critical). Weightless, noiseless plate and mail (A.R. 17, S.D.C. 160); Cloak of Iron (A.R. 15, S.D.C. 300). Magical lyre, mandolin and flute that float and play by themselves for up to an hour (about 100,000 gold as a set). Giant-sized Dwarven ball and chain (4D6+4, +1 parry and strike), battle axe (4D6+4, +2 parry and strike), claymore (4D6+4, +1 strike and parry).', 'Strongbox of 25,000 in Old Kingdom gold, 10 diamonds worth 5,000 gold each, and a necklace of 12 dragon''s teeth (40,000 gold each, 480,000 in all) that he will not part with', 'Unshakeable in his alignment, fearless, generous to a fault and a rallying figure for those beside him.', 'The Serelan Tribe', 'The Idrijian Tribe; powerful foes made on the surface', 'Serelan hero back from his seventh journey across the surface world, now leading the guerrilla campaign that is grinding down the Idrijian. Made his tooth necklace from a Fire Dragon he killed.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.165-166'),
('cowedo-gatisi', 'Cowedo Gatisi', NULL, 'Leader of the Idrijian Tribe', 'palladium-fantasy', 'Minotaur', '7th level Thief and 4th level Witch of the Old Ones', 7, 'Miscreant', '340', NULL, NULL, '{"IQ":10,"ME":15,"MA":14,"PS":24,"PP":21,"PE":23,"PB":3,"Spd":17}', 75, 90, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, 'Witch of the Old Ones; no spells or gifts are listed.', NULL, NULL, NULL, NULL, NULL, 'Desperate enough at losing the war to bind his followers to the Old Ones.', 'The Idrijian Tribe, 40 of whose warriors he has made 1st or 2nd level witches', 'Xexin Vidaav and the Serelan Tribe', 'Chief of the 250 raiding Idrijian Minotaurs, who are losing three warriors for each Serelan they kill.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.166'),
('bimmid-the-bold', 'Bimmid the Bold', NULL, NULL, 'palladium-fantasy', 'Quillback', '11th level Quillback Scavenger', 11, 'Unprincipled', NULL, NULL, NULL, '{"IQ":20,"ME":18,"MA":13,"PS":10,"PP":22,"PE":11,"PB":14,"Spd":32}', 55, 30, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Environmental Tent, Pillow of Sleep, Fire Wick, Container of Much Water; a Cloak of the Chameleon (the 1st level Earth Elemental spell Chameleon, always on) hung over his cave mouth so it passes for stone; a Magic Roman Candle firing 20 sparks a day, up to 4 per volley with a separate strike roll each.', NULL, 'A trickster who beats larger foes by wits, nerve and luck, lately hunting only for comforts.', 'Rocky Desert Quillbacks, to whom he is a hero', 'The many Orcs, Ogres, Trolls and giants he has conned or robbed', 'The best-known Quillback of the Rocky Desert, living in a small cave fitted out with stolen magical luxuries.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.166-167');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('janihill', 'Janihill', NULL, NULL, 'palladium-fantasy', 'Quillback', '5th level Quillback Shaman', 5, 'Scrupulous', NULL, NULL, NULL, '{"IQ":14,"ME":11,"MA":23,"PS":6,"PP":21,"PE":8,"PB":13,"Spd":20}', 33, 10, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Owns nothing; gives away what she finds.', NULL, 'Warm, well-informed and quick to befriend strangers, with no interest in treasure.', NULL, NULL, 'Female Quillback who has made herself guardian of the Rocky Desert, roaming it to help newcomers and anyone in need.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.167'),
('tchkiskisk', 'Tchkiskisk', NULL, NULL, 'palladium-fantasy', 'Quillback', '4th level Quillback Scavenger', 4, 'Unprincipled', NULL, NULL, NULL, '{"IQ":20,"ME":20,"MA":13,"PS":10,"PP":22,"PE":10,"PB":9,"Spd":23}', 30, 20, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, 'Taught himself to write Elven.', NULL, NULL, NULL, NULL, NULL, 'A magical quill of endless ink and three large spent spell books whose pages, once scrolls, are now blank.', NULL, 'Wily, and so hooked on his daily writing that the shortage of paper may push him into risky schemes.', 'Quillbacks generally, who love his readings', NULL, 'The Quillbacks'' chronicler, who fills salvaged spell books with accounts of his own adventures and is running out of pages.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.167'),
('jijjerijn-the-magnificent', 'Jijjerijn the Magnificent', NULL, 'Supreme Commander of Raag Vire and Lord of the Baalgor Gromek', 'palladium-fantasy', 'Gromek', '12th level Knight', 12, 'Aberrant', NULL, NULL, NULL, '{"IQ":13,"ME":16,"MA":12,"PS":24,"PP":18,"PE":24,"PB":12,"Spd":12}', 84, 50, NULL, NULL, NULL, 15, NULL, '{"attacks":8,"initiative":1,"strike":4,"parry":9,"dodge":9,"roll":4,"pull":3,"damage":13}', 'Spd is printed as 12 running and 40 flying. +2 to disarm, +5 to save vs magic and poison, +18% vs coma/death. Critical strike 18-20, KO on a natural 20, leap attack (critical strike), all jump kicks, body flip/throw. A.R. 15 is his plate and chain armor (100 S.D.C.).', NULL, 'Hand to Hand: Martial Arts and Boxing. W.P. Paired Weapons; W.P. Lance (the block defers to the Knight O.C.C.); W.P. Sword (+5 strike, +4 parry, +3 throw); W.P. Shield (+5 parry, +3 strike); W.P. Battle Axe (+5 strike/parry/throw, +1D6 damage); W.P. Spear (+5 strike/parry, +3 throw); W.P. Chain (+4 strike, +3 parry); W.P. Pole Arm (+5 strike/parry, +4 damage, +3 throw).', 'Winged; flies at Spd 40.', 'None of his own. The Northern Fury lets its wielder cast, at 6th level proficiency and up to three times daily in any combination: Freeze Water, Sheet of Ice, Shards of Ice, Wall of Ice, 10 Foot Ball of Ice, Encase in Ice.', NULL, NULL, NULL, 'The Axe of Elmorik: indestructible one-handed double-bladed battle axe, 3D6; non-magical weapons and shields that parry it must save vs magic (12 or higher) or shatter. The Northern Fury: long sword, 4D6, victim saves vs magic or is paralyzed one melee round; wielder immune to normal cold and takes half from magical cold; 500 S.D.C., regenerates 20 per hour. Plate and chain armor (A.R. 15, S.D.C. 100). Assorted magic weapons and items kept at the Command Post, among them potions, fumes and 30 Lightning javelins.', 'A hoard under his command post floor, contents unspecified; at least 1D6 million in gold, silver and gems.', 'Hard, cool-headed and honorable by Gromek lights; patient, wearing the giants down with small raids instead of open battle.', 'The unified Gromek tribes of the Baalgor Mountains; the wizard Qsin Lirieq', 'The giants of Gurthasi Tor and the Nimro Kingdom', 'Gromek warlord who lost Mount Nimro to the giants, fell back to the eastern Baalgor range and built Raag Vire into the heart of the Gromek resistance.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.177-178'),
('ghrrh-tyriun', 'Ghrrh Tyriun', NULL, 'Combat mage of Raag Kodigy', 'palladium-fantasy', 'Gromek', '7th level Wizard', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":11,"ME":12,"MA":9,"PS":20,"PP":15,"PE":15,"PB":10,"Spd":11}', 33, 30, NULL, 205, NULL, 12, NULL, '{"attacks":5,"strike":1,"parry":2,"dodge":2,"roll":2,"pull":2,"damage":7}', 'Spd is printed as 11 running and 30 flying. +3 to save vs magic, +2 to spell strength. Critical strike 19-20. A.R. 12 is natural; he wears no armor.', NULL, 'Hand to Hand: Basic.', 'Winged; flies at Spd 30. Natural A.R. 12.', 'All common knowledge spells plus See the Invisible, Sense Magic, Fear, Mystic Alarm, Armor of Ithan, Energy Bolt, Carpet of Adhesion, Breathe Without Air, Fire Bolt, Fire Fist, Call Lightning (printed ''Call Lighting''), Life Drain, Sickness, Wink-Out, Eyes of Thoth.', NULL, NULL, NULL, 'No weapons and no armor, out of pride in his spell casting. Ring of Sustenance (no need for food, drink or rest while worn).', NULL, 'Plays the loyal soldier in front of other Gromek while putting himself first; a would-be tyrant hunting the lost art of Life Force Wizardry.', 'A small corps of Gromek combat wizards he leads on raids', NULL, 'Gromek wizard who volunteered for Raag Kodigy only to be near caves he hopes hold the secrets of Life Force Wizardry.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.183'),
('gojor', 'Gojor', NULL, 'Master ballista gunner of Gurthasi Algor', 'palladium-fantasy', 'Nimro', '9th level Long Bowman', 9, 'Anarchist', NULL, NULL, NULL, '{"IQ":8,"ME":17,"MA":6,"PS":20,"PP":23,"PE":23,"PB":8,"Spd":9}', 63, 70, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, 'Expert with siege weapons, the ballista above all.', NULL, NULL, NULL, NULL, NULL, 'Mans a ballista; no personal gear is listed.', NULL, 'Silent and dour, with little life beyond his post; asked for the cold stronghold out of curiosity and likes it.', 'The giant garrison of Gurthasi Algor', 'Gromek', 'Nimro marksman famed for shooting flying Gromek out of the air at extreme range, waiting hours at his ballista for one clean shot.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.188'),
('orgath-nukessin', 'Orgath Nukessin', NULL, 'Overlord of Gurthasi Tor and High Commander of the Baalgor Army', 'palladium-fantasy', 'Nimro', '10th level Nimro Soldier', 10, 'Aberrant', NULL, NULL, NULL, '{"IQ":14,"ME":14,"MA":22,"PS":30,"PP":21,"PE":30,"PB":13,"Spd":26}', 75, 90, NULL, NULL, NULL, 17, NULL, '{"attacks":8,"initiative":1,"strike":6,"parry":8,"dodge":8,"damage":17,"pull":4,"roll":5}', '+2 to disarm, +8 to save vs magic and poison, 70% to evoke trust or intimidation, +2 to save vs H.F., +3 to save vs possession. Critical strike 18-20, KO on natural 20, backward sweep, tripping/leg hook, all jump kicks, leap attack (critical strike). His sword adds one attack per melee; the block does not say whether the printed 8 includes it. A.R. 17 is his plate mail (200 S.D.C.). The gauntlet parries at +7.', NULL, 'Hand to Hand: Martial Arts and Boxing. W.P. Paired Weapons; W.P. Sword (+4 strike/parry, +2 throw); W.P. Shield (+4 parry, +2 throw); W.P. Chain (+4 strike, +2 parry); W.P. Siege Weapons (+3 strike); W.P. Pole Arms (+4 strike/parry/dodge, +2 throw).', 'Breathes fire, as the combat line notes; no damage or range is printed here.', 'None of his own; see his items (Tongues at will from a necklace; the Dread Pendant summons Baal-rogs).', NULL, NULL, NULL, 'Enchanted long sword (3D6+2): indestructible, warns him of Changelings within 100 ft, adds one attack per melee. Plate mail of excellent quality (A.R. 17, S.D.C. 200). Tentacle gauntlet on the left arm: four tentacles reaching 20 ft that handle objects like a hand, whip for 3D6, constrict for 2D6 per melee (P.S. 25), parry at +7; each tentacle A.R. 15, S.D.C. 50; gauntlet A.R. 15, S.D.C. 270, regenerates 10 per hour, resizes to any wearer. Necklace granting Tongues at will. Lesser potions, scrolls and talismans. The Dread Pendant: gives the true names of the eight Baal-rogs of the Council of Doom, summons and commands one at a time, and makes the wearer immune to the magic and psionics of all Baal-rogs; the other seven hunt whoever uses it. He wears it always and has never used it.', 'Millions in gold, gems and jewelry: one million at the Hall of Nukessin, one at Troker, one at the Isle of the Cyclops, the rest hidden in or near Mount Nimro.', 'Ruthless but even-handed patriot of the giant cause who does his best work under strain and tolerates no slack from anyone beneath him.', 'Sunder Blackrock and the Nimro Kingdom of Giants; The Dozen, his council of twelve; Yev the Merciless, his Ogre butler; the Gosai clan of Shesesseth Skai', 'The Gromek of the Baalgor Mountains; Igrig Odgol wants him dead', 'Founder and ruler of Gurthasi Tor, charged with driving the Gromek out of the Baalgor Mountains and scouting the Wastelands for the giant kingdom.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.192-194'),
('reginald-cuthbert-swenley', 'Reginald Cuthbert Swenley', NULL, 'Master of the Gurthasi Tor Slaughteryards', 'palladium-fantasy', 'Gigante', '5th level Vagabond', 5, 'Miscreant', NULL, NULL, NULL, '{"IQ":6,"ME":1,"MA":4,"PS":32,"PP":24,"PE":30,"PB":2,"Spd":32}', 60, 130, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line. The S.D.C. already includes +40 from scaly skin and the Spd already includes +20 from his extra leg. Insanities: semi-functional mindless aggression and mild manic depression.', NULL, '+20% to balance from the extra leg; no base percentage is printed.', 'Gigante mutations: scaly skin, vestigial feathered wings that cannot lift him, large fangs, and a third leg.', NULL, NULL, NULL, NULL, 'A giant-sized maul he calls Reggie''s Little Helper; no damage is printed for it.', NULL, 'Raving mad and convinced he is a gentleman of noble birth; sinks into black moods on any day he kills nothing, and those moods can turn on his workers.', 'A staff of 30 Orcs and 40 Ogres', NULL, 'Insane Gigante who personally kills every animal at the city slaughterhouse and is rumored to eat the odd Orc.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.196'),
('shesesseth-skai', 'Shesesseth Skai', NULL, 'Leader of the Gosai clan at Gurthasi Tor', 'palladium-fantasy', 'Gosai', '6th level Gosai Assassin R.C.C.', 6, 'Anarchist', NULL, NULL, NULL, '{"IQ":13,"ME":12,"MA":13,"PS":15,"PP":20,"PE":17,"PB":11,"Spd":15}', 42, 40, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The clan is paid room, board and 5,000 gold a month.', 'A hired professional; no personality is given beyond the contract.', '14 other Gosai assassins of 2nd to 4th level; employer Orgath Nukessin', 'Gromek commanders', 'Gosai clan chief whose assassins spy on Gromek territory and kill its leaders for the Overlord, to the disgust of most of the city''s giants.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.198'),
('vssclp-tlall', 'Vss''clp Tl''all', NULL, 'Head of the Cyclops delegation at Gurthasi Tor', 'palladium-fantasy', 'Cyclops', '6th level Noble, 5th level Knight', 6, 'Aberrant', NULL, NULL, NULL, '{"IQ":14,"ME":6,"MA":21,"PS":26,"PP":18,"PE":20,"PB":9,"Spd":15}', 70, 100, NULL, NULL, NULL, NULL, NULL, NULL, 'Only attributes, Hit Points and S.D.C. are printed; no combat line.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A diplomat on a trial mission; no personality is given.', '17 other Cyclops: four personal attendants, three Gryphon Trainers, three Lightning-Smiths and seven soldier-advisors', NULL, 'Cyclops envoy leading the eighteen advisors who quietly supply Gurthasi Tor with lightning weapons and trained gryphons in breach of their treaty with the Western Empire.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.198'),
('wydras-the-dreamer', 'Wydras the Dreamer', NULL, NULL, 'palladium-fantasy', 'Thunder Lizard (dragon)', 'Adult Thunder Lizard', NULL, 'Unprincipled', NULL, NULL, NULL, '{"IQ":26,"ME":26,"MA":26,"PS":34,"PP":22,"PE":26,"PB":32,"Spd":56}', 3026, 2000, NULL, 950, NULL, 15, 15, '{"attacks":7,"initiative":4,"strike":7,"dodge":7,"roll":4,"pull":5,"damage":19}', 'P.S. 34 is supernatural. Attacks per melee: 7 physical, or 4 fire breath, or 2 by magic. The line gives +4 to roll with impact and then a second, bare +8 to roll. +4 on all saving throws, +6 vs Horror Factor. No parry bonus is printed. A.R. 15 is natural. Alignment drifts to Anarchist or even Miscreant for the first 1D4 hours after he wakes. The prose calls him ancient and an elder dragon; the O.C.C. line says Adult.', '[{"name":"Teleport self","pct":88},{"name":"Dimensional teleport","pct":78}]', NULL, 'Nightvision 100 ft, excellent color vision, sees the invisible, turns invisible at will, prehensile tail, regenerates 1D4x10 H.P./S.D.C. per minute, half damage from cold and fire, shape-changes at will (6 hour limit), self-teleport 88%, dimensional teleport 78%, plus the other dimensional powers of true dragons. Green Fire Breath: a poison vapor 100 ft long and 6 ft wide, usable four times a melee, catching 2-6 targets standing close; mortals take 1D6 and are paralyzed 1D6 melees unless they save vs magic at 14, supernatural beings and dragons take 3D6, Elementals 6D6.', 'All wizard spells of levels one through fourteen, plus the dimensional spells common to true dragons.', NULL, NULL, NULL, 'None carried. His lair holds a hoard gathered over millennia; contents are left to the G.M.', 'Hoard unspecified; a robber is unlikely to escape with more than a couple of items and 1D6x10,000 in gold and gems.', 'Not cruel, but furious at being woken and expecting grovelling apologies; disables good and selfish foes and shows evil ones no mercy. Dislikes Gromek.', 'Might agree to a mutual-defense pact with Orgath Nukessin', NULL, 'Ancient dragon asleep at the foot of the Gurthasi Tor plateau, right where the giants'' practice rocks and arrows come down.', 'Palladium Fantasy RPG Book 9: The Baalgor Wastelands p.200-201');
