-- Palladium Fantasy RPG Book 9: The Baalgor Wastelands - its bestiary and its notable NPCs.
-- 24 creatures (migration 074) and 60 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~180-baalgor-wastelands-creatures-and-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.









-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 24 creatures are in' AS assertion, count(*) AS got, 24 AS want
  FROM creatures WHERE slug IN ('baalizad', 'cyclops-spider', 'dragonman', 'drayback', 'eandroth-pf', 'earthshaker', 'cyclops', 'jotan', 'gigantes', 'nimro', 'gosai', 'gromek-pf', 'lazretheg', 'minotaur', 'mologoth', 'quillback', 'quorian', 'rock-buzzer', 'sandwyrm-pf', 'sloderi', 'thin-one', 'vrill', 'adraodan-minotaur', 'kkairojan-minotaur');
SELECT 'and 15 of them are playable' AS assertion, count(*) AS got, 15 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('baalizad', 'cyclops-spider', 'dragonman', 'drayback', 'eandroth-pf', 'earthshaker', 'cyclops', 'jotan', 'gigantes', 'nimro', 'gosai', 'gromek-pf', 'lazretheg', 'minotaur', 'mologoth', 'quillback', 'quorian', 'rock-buzzer', 'sandwyrm-pf', 'sloderi', 'thin-one', 'vrill', 'adraodan-minotaur', 'kkairojan-minotaur');
SELECT 'all 60 notable NPCs are in' AS assertion, count(*) AS got, 60 AS want
  FROM notable_npcs WHERE slug IN ('jaheris-scarbone', 'tsirkan', 'agrami', 'manaash', 'argullud-zugon', 'gakrung-the-widowmaker', 'graven-killjoy', 'jammer', 'shade-pirate-lord', 'mojo-pirate-lord', 'konilock-of-the-flame', 'byzantium-freck', 'leslo-squibbs', 'seremm-the-gray', 'azamon-redlin', 'king-kai-the-wanderer', 'firyin-kath', 'deggh-courlik', 'kimona-lasaatki', 'grovoss', 'kongo-the-kurayguss', 'gramazz-the-gray', 'rogayashi', 'grillek-ibesstissen', 'agek-ta-k-t-kusssa', 'egreiga-koge', 'ab-al', 'mubulu', 'churluo', 'xevesstssn', 'commander-orgizeg', 'ferigut', 'nekaradon', 'gruegas-wierdling', 'unom', 'skddn-ros-kdda', 'commander-stone-hammer', 'goliko-edrex', 'lldirrn', 'quake-algor', 'ckurlka', 'keisel-the-undying', 'luurna', 'ziiclymnt', 'grounna', 'mergerij', 'zeelik-stonemace', 'xexin-vidaav', 'cowedo-gatisi', 'bimmid-the-bold', 'janihill', 'tchkiskisk', 'jijjerijn-the-magnificent', 'ghrrh-tyriun', 'gojor', 'orgath-nukessin', 'reginald-cuthbert-swenley', 'shesesseth-skai', 'vssclp-tlall', 'wydras-the-dreamer');
SELECT 'the creatures carry 86 attacks' AS assertion, count(*) AS got, 86 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('baalizad', 'cyclops-spider', 'dragonman', 'drayback', 'eandroth-pf', 'earthshaker', 'cyclops', 'jotan', 'gigantes', 'nimro', 'gosai', 'gromek-pf', 'lazretheg', 'minotaur', 'mologoth', 'quillback', 'quorian', 'rock-buzzer', 'sandwyrm-pf', 'sloderi', 'thin-one', 'vrill', 'adraodan-minotaur', 'kkairojan-minotaur');
SELECT 'and the notables 130' AS assertion, count(*) AS got, 130 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('jaheris-scarbone', 'tsirkan', 'agrami', 'manaash', 'argullud-zugon', 'gakrung-the-widowmaker', 'graven-killjoy', 'jammer', 'shade-pirate-lord', 'mojo-pirate-lord', 'konilock-of-the-flame', 'byzantium-freck', 'leslo-squibbs', 'seremm-the-gray', 'azamon-redlin', 'king-kai-the-wanderer', 'firyin-kath', 'deggh-courlik', 'kimona-lasaatki', 'grovoss', 'kongo-the-kurayguss', 'gramazz-the-gray', 'rogayashi', 'grillek-ibesstissen', 'agek-ta-k-t-kusssa', 'egreiga-koge', 'ab-al', 'mubulu', 'churluo', 'xevesstssn', 'commander-orgizeg', 'ferigut', 'nekaradon', 'gruegas-wierdling', 'unom', 'skddn-ros-kdda', 'commander-stone-hammer', 'goliko-edrex', 'lldirrn', 'quake-algor', 'ckurlka', 'keisel-the-undying', 'luurna', 'ziiclymnt', 'grounna', 'mergerij', 'zeelik-stonemace', 'xexin-vidaav', 'cowedo-gatisi', 'bimmid-the-bold', 'janihill', 'tchkiskisk', 'jijjerijn-the-magnificent', 'ghrrh-tyriun', 'gojor', 'orgath-nukessin', 'reginald-cuthbert-swenley', 'shesesseth-skai', 'vssclp-tlall', 'wydras-the-dreamer');

